INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60239, '2026-10-01', '東京都', '銕仙会企画 2026年後期 公開講座と能鑑賞 講座「能『野宮』の魅力を探る」', '銕仙会能楽研修所', '18:30', '銕仙会能楽研修所（鑑賞は観世能楽堂） 第1回 10月1日18時半 1、能「野宮」を読む 高橋 悠介 2、実技（アシラヒによる） 葵上クドキ〜中入迄シテ 馬野 正基 ツレ 小早川康充 地謡 柴田 稔 北浪 貴裕 安藤 貴康 青木 健一 アシラヒ 鵜澤 久 第2回 10月9日18時＊定期公演鑑賞 舞囃子「山姥」大槻文藏 狂言「魚説法」野村萬 能「野宮」観世淳夫 第3回 10月15日18時半 1、実技 仕舞 定家 清水 寛二 玉鬘 鵜澤 光 地謡 西村 高夫 小早川 修 鵜澤 久 小早川泰輝 2、対談 能「野宮」解釈と演出 高橋 悠介 観世銕之丞 講師 高橋悠介 ●全3回通し券（鑑賞指定券含む）一般8000円 U２５（２５歳以下）5000円 講座1回券 一般2000円 U２５（２５歳以下）1500円 ■お申込み・お問合せ先 銕仙会(てっせんかい) TEL.03-3401-2285（平日10時-17時）FAX.03-3401-2313 http://www.tessen.org/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#49078', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60240, '2026-10-02', '京都府', 'デジタル能舞 ｉｎ 高台寺', '鷲峰山 高台寺', '18:00', '18:00 〜21:30 （最終入場 21:00） 鷲峰山 高台寺 能舞公演 開始時間（実施場所） 18:30（方丈内）、19:30（勅使門前）、20:30（方丈内） ※3日間共通、各15分、方丈内2回/勅使門前1回 能舞演目「羽衣（はごろも）」 出演者 : 片山 九郎右衛門（かたやま くろうえもん、10月2日(金)）、分林 道治（わけばやし みちはる、3日(土)・4日(日)） ●大人:2,500円中高生:1,000円（小学生以下無料） ※当日は、演出の関係上、開山堂の拝観はできません。 https://www.teamfire-kodaiji.jp/ チケットはこちらから チケットぴあ https://t.pia.jp/pia/ticketInformation.do?eventCd=2637219&rlsCd=001 Peatix https://kodaiji-noumai2026.peatix.com/view', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51689', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60241, '2026-10-02', '京都府', 'ＥＮＴＥＲ ＮＯＨ Day１ Masked Stage Art of Japan', '京都観世会館', '17:00', '１９：００開演 京都観世会館 ※本公演は外国人向けの特別イベントです。 英語解説 Diego Pellecchia ★能 船弁慶 前後之替 味方 團 田茂井廣道 ―Ticket Prices(tax included)― Special Backstage tour +A Seat(1F Reserved seat) \27,000 ☆17:00〜 20名様限定のﾊﾞｯｸｽﾃｰｼﾞﾂｱｰ A Seat(1F Reserved seat) \13,000 B Seat (1F Partially obstructed-view seat) \11,000 Student Seat* (2F Non-Reserved seat) \4,000 https://kyoto-kanze.jp/lp/20261002show_meeting/?_gl=1 *mgl7pg*_gcl_au*MTIyNjQwMDI5OC4xNzg2Nzc0Nzc3', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51739', 0, 0);
