INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60274, '2026-10-04', '京都府', '2026年度 シリーズ能楽講座 能楽師有松遼一の「はじめての能！ 」〜能のことば、和歌のことば〜【旧三井家下鴨別邸】', NULL, NULL, '【場 所】 旧三井家下鴨別邸 2階座敷 【シリーズテーマ】 能のことば、和歌のことば 【日時と演目】 第1回：4月4日（土） 能《百万》と「みどり」 第2回：7月12日（日） 能《蘆刈》と「なにわ」 第3回：10月4日（日） 能《松風》と「面影」 第4回：12月19日（土） 能《雪》と「朝ぼらけ」 【時 間】 10：30〜12：00 【内 容】 ・資料や映像で能の“味わい方”をやさしく解説 ・謡の体験と実演鑑賞 ・1階座敷にて抹茶とお菓子付き 【定 員】 20名程度 【料 金】 4,000円税込 （抹茶券付、入館料600円別途） ※当日受付にてお支払い 【講師】 有松 遼一 ありまつ りょういち お問い合わせ 事前申込み制。 メールにてお申し込み。 メールでのお申込み arimatsu.noh.office☆gmail.com ☆を＠に変えて送信 以下の内容を記載の上、送信してください。 �@イベント名「はじめての能！」 〇月の部とご記載ください。 �A代表者氏名 �B参加人数 �C電話番号 �D住所 �Eメールアドレス お申込み受付回答 返信メールでの回答をもって予約の成立といたします。 迷惑メール対策をされている場合、ドメインgmail.comのメールを受信できるよう設定願います。 申込締切 定員に達し次第、受付終了。 ■お問い合わせ 旧三井家下鴨別邸TEL：075-366-4321（9：00〜17：00※水曜休館） TEL 075-366-4321 お問い合わせURL https://ja.kyoto.travel/tourism/article/mitsuike/ https://ja.kyoto.travel/event/single.php?event_id=14053', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50970', 0, 0);
