INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60320, '2026-10-09', '東京都', '台東学びのひろば『能楽入門&講義と実技（謡曲と所作）で学ぶお能の世界;』台東区在住・在勤・在学の方限定', NULL, '08:00', '日 程：１０月９日〜２月１１日 金曜日（※１０月３０日、１１月２７日は休講） 時 間：１８時３０分〜２０時３０分 全８回 開催館 ：台東区立 社会教育センター 対 象：台東区在住・在勤・在学の１６歳以上の方 定 員：２０名 講師 坂 真太郎 教材費：２２００円 持ち物：白ソックス（あれば白足袋）、 お持ちの方で必要であればボイスレコーダーなどの録音機器 9月17日締切（必着） 《申込方法》 往復はがき、又は台東区立社会教育センター・社会教育館のホームぺージにてお申込みください。（応募者多数の場合は抽選） https://www.taito-shakyo.com/center-ts/lecture01/type02/ はがきの記入内容などの詳細は、広報たいとう８月20号をご覧いただくか、下記までお問合せください。 《申込み・問合せ先》 台東区立社会教育センター 〒１１０−００１５ 台東区東上野６−１６−８ ＴＥＬ：０３−３８４２−５３５２ ※第１・３・５月曜午前休館 https://www.shinnohsho.net/post/%E5%8F%B0%E6%9D%B1%E5%8C%BA%E5%9C%A8%E4%BD%8F%E3%83%BB%E5%9C%A8%E5%8B%A4%E3%83%BB%E5%9C%A8%E5%AD%A6%E3%81%AE%E6%96%B9%E9%99%90%E5%AE%9A%EF%BC%81%E5%8F%B0%E6%9D%B1%E5%AD%A6%E3%81%B3%E3%81%AE%E3%81%B2%E3%82%8D%E3%81%B0%E3%80%8E%E8%83%BD%E6%A5%BD%E5%85%A5%E9%96%80%E3%80%9C%E8%AC%9B%E7%BE%A9%E3%81%A8%E5%AE%9F%E6%8A%80%EF%BC%88%E8%AC%A1%E6%9B%B2%E3%81%A8%E6%89%80%E4%BD%9C%EF%BC%89%E3%81%A7%E5%AD%A6%E3%81%B6%E3%81%8A%E8%83%BD%E3%81%AE%E4%B8%96%E7%95%8C%E3%80%9C%E3%80%8F-%E9%96%8B%E5%82%AC%E3%81%AE%E3%81%8A%E7%9F%A5%E3%82%89%E3%81%9B', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51660', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60321, '2026-10-09', '東京都', '第40回月窓寺 吉祥寺薪能', '横浜能楽堂', '17:00', '17時15分 吉祥寺 月窓寺境内 【雨天時会場】 武蔵野市民文化会館 狂言解説：中村修一 火入れの儀 狂言『呂蓮』野村万作 野村萬斎 高野和憲 能解説：中村雅之（横浜能楽堂芸術監督） 能『土蜘蛛 さゝ蟹』観世喜正 奥川恒治 佐久間二郎 金子仁智翔 舘田善博 則久英志 渡部葵 内藤連 飯田豪 笛 一噌隆之 小鼓 田邊恭資 大鼓 柿原弘和 太鼓 林雄一郎 地頭 中所宜夫 【チケット発売日】 8月20日（木） ●全席指定 A席5000円 B席3500円 電話予約は出来ません 武蔵野市観光機構 商工会館1階 9時半より販売 9時半から17時半受付 JTB吉祥寺店 10時より販売 10時から17時半受付 https://yarai-nohgakudo.com/archives/13787 https://musashino-kanko.com/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51421', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60322, '2026-10-09', '東京都', '銕仙会 定期公演', '観世能楽堂', '18:00', '18時 観世能楽堂 ★舞囃子 山姥 大槻文蔵 笛 一噌庸二 小鼓 曽和伊喜夫 大鼓 亀井洋佑 太鼓 三島元太郎 ★狂言 魚説法 野村萬 野村万之丞 ★能 野宮 観世淳夫 福王和幸 野村万蔵 笛 杉信太朗 小鼓 大倉源次郎 大鼓 大倉慶乃助 地頭 観世銕之丞 ●Ｓ席 7,000円 Ａ席 6,000円 Ｂ席 5,000円 Ｃ席 4,500円 U25（25歳以下） 2,700円 銕仙会定期公演・青山能共通回数券（5枚綴り） 一般22000円 Ｕ２５（25歳以下）10000円 1月定期公演は除く 定期公演はＢ席脇正面、青山能は自由席と引き換え 当日空席あれば追加で座席変更可能 ■お問い合わせ・お申込み 銕仙会 03-3401-2285 （平日10：00−17：00）FAX 03-3401-2313 http://www.tessen.org/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#48701', 0, 0);
