INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60324, '2026-10-09', '神奈川県', '第68回 鎌倉薪能', '鎌倉芸術館', '17:00', '開場 17時 開演 18時 終演 20時30分頃予定 鎌倉宮境内（鎌倉市二階堂154） ※雨天の場合は、鎌倉芸術館大ホールにて開催 ★素謡「翁」 金春 憲和（金春流81世宗家） ★狂言「清水」 野村 裕基（和泉流） ★能「黒塚」 金春 安明（金春流80世) ●S席 12,000円、A席 9,000円（後方部ひな檀）、B席 7,000円（各税込み） 全席指定／解説入りパンフレット付き ※解説入りパンフレットは当日受付にてお配りいたします 発売 2026年8月22日（土）10時 700席（先着順） お申し込み先：CNプレイガイド WEBまたはお電話、ファミリーマート店頭「マルチコピー機」(下記表を参照)にてお申し込みください。 【2026年8月22日(土)10時00分から受付開始】 ※TEL番号およびWEBサイトは受付開始日に合わせて開通予定です。 お申し込み先：CNプレイガイド TEL 0570-08-9999 WEB https://www.cnplayguide.com/kamakura-takiginoh/ https://www.trip-kamakura.com/subsite/detail.php?id=13', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50239', 0, 0);
