INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60333, '2026-10-10', '岡山県', 'おかやまアーツフェスティバル2026 能と箏が織りなす幽玄の世界 舞台「甚九郎稲荷物語 〜岡山・追憶の舞〜」', NULL, '14:15', '開場 14:15 / 開演 15:00 終演 16:30(予定) 能楽堂ホールtenjin9（岡山市北区天神町9-24 RSK山陽放送1F） 第 1 部 能と箏が織りなす幽玄の世界 舞台 「甚九郎稲荷物語 〜岡山・追憶の舞〜」 【キャスト】 豪 姫 ･ 白 狐 ： 伶以野 陽子 (シテ方 観世流 能楽師) 宇喜多 秀家 ： 梅若 基徳 (シテ方 観世流 能楽師 重要無形文化財総合認定保持者) 佐久間甚九郎 ： 後藤 勝徳 (一般社団法人 歴史新大陸 代表理事) 豪姫付き人 ： 広坂 武昌 (田賀屋狂言会 事務局長) 【演 奏 者】 箏 ： 山路 みほ （箏曲演奏家) 尺 八 ： イオ・パヴェル （尺八奏者) 【語 り 部】 遠藤 寛子（フリーアナウンサー） 第 2 部 「アフタートーク」 舞台出演者 ： 伶以野 陽子、梅若 基徳、後藤 勝徳、広坂 武昌、山路 みほ、イオ・パヴェル 遠藤 寛子 特別ゲスト ： 内池 英樹 （岡山県立博物館 副館長） 原案 舞台「甚九郎稲荷物語〜秀家が愛した岡山、稲荷社の守り人〜」(後藤 勝徳) ●前売券 &#10112; 一般 5,000円 �A U19(19歳以下) 1,000円 (公演日の時点で19歳以下対象。ご入場時に生年月日が確認できるものをご持参下さい) �B 一般ペア割引券 9,000円(2名同時入場に限ります) 税込・全席自由・未就学児入場不可 当日500円UP（当日�Bの販売はありません) チケット販売 一般発売日 7月19日(日) (※)は7月21日(火) RSKチケット https://www.cnplayguide.com/rsk-ticket/ 香川県県民ホールサービスセンター 087-823-5023 (10:00〜18:00) https://kenminhall.com/visitors/ticket/ 岡山芸術創造劇場ボックスオフィス TEL：086-201-2200(休館日除く 10:00〜18:00) 岡山県音楽文化協会(※) TEL：086-224-6066(平日9:00〜17:00／土曜日・日曜日・祝日 休) ぎんざや TEL：086-222-3244(10:00〜18:00／不定休) 山陽新聞社サービスセンター(※) TEL：086-803-8222(平日10:00〜16:00／13:00〜14:00昼休業、土曜日・日曜日・祝日 休) イープラス https://eplus.jp/jinkuro/ チケットぴあ https://t.pia.jp/ 【Pコード：543-885】 ローソンチケット https://l-tike.com/order/?gLcode=62812 【Lコード：62812】 CNプレイガイド https://www.cnplayguide.com/jinkuro/ 0570-08-9999 受付時間（年中無休10:00〜18:00） 来場者特典：当日、岡山神社(甚九郎稲荷神社を管掌)へお参りすると、公演チケット提示で、この日限りの“記念ご朱印”が授与されます(初穂料500円)。 連携事業 郷土の食と芸能と歴史の祭典！ 秋のおかやま桃太郎まつり 会期:10月10日(土)・11日(日)10:00-17:00 会場:岡山城一帯 主催:おかやま桃太郎まつり運営委員会 ◎城郭・武将イベント「集え!岡山城」も同時開催！ お問い合わせ RSK山陽放送 事業開発部 TEL:086-225-7300 (平日10:00〜17:00) メールアドレス：jin@rsk.co.jp https://www.rsk.co.jp/event/ticket/jinkuroinari_20261010.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51410', 0, 0);
