INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60412, '2026-10-16', '大阪府', 'ハマってみよう！謡の世界！PLUS_2026‐15 Zoom講座ですが主催が大阪なので開催地大阪にしております。', NULL, '18:00', '18:00開演 Zoom（オンライン） 2,000円(神社講座またはZoom講座２回参加費用) ※講座申込み完了後、参加費の振込先を御連絡致します 謡講座 （Zoom講座は60分） ◆開催日◆ 10月16日(金)、10月30日 (金) 18:00〜19:00 ※通信環境・Wi-fi環境のある方は是非。お振込後 Zoom 接続テストも行います。 ◆募集人数◆ 10名 ◆参加資格◆ どなたでも参加できます (現在謡をお稽古されている方はご遠慮頂く場合がございます) ※Zoom 講座をご希望の方は、 通信環境の設定の有る方が申込可能です。 (パソコン・タブレット・スマートフォン等お持ちで御自宅に Wi-Fi 環境の有る方) お振込後 Zoom 接続テストも行います。 ◆お申込み方法◆ 締め切り：2026年5月17日(日)18:00 お申込みフォームに内容を記載してお申し込みください。 フォームで入力ができない方は、MAIL[hamattemiyou.utai@gmail.com] に 氏名／住所／電話番号／希望する会場を第２希望まで記載の上、ご送信ください。 尚、講師・会場の都合などにより日時が変更となる場合がございます。 ◎講座申込み完了後 参加費の振込先を御連絡致します。 お問い合わせ 070-4458-8833（平日 12:00〜19:00）公益社団法人能楽協会 大阪支部 謡文化再生事業部 ※お電話は直ぐにご対応出来ない場合もございますので御了承下さい。 https://www.nohgaku.or.jp/performance/hamatte_20261016-15', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50671', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60413, '2026-10-16', '東京都', '能役者が語る鬼の能 第6回 砕動の鬼(4)「山姥その2」', '矢来能楽堂', '14:00', '14:00（開場13:30） 場所：神楽坂 矢来能楽堂（東京都新宿区矢来町６０） 講師 味方玄 ●参加費：4,000円／青少年1,000円（満12才〜26才未満の学生の方・学生証提示） ※青少年割引の対象:満 12才 ~ 26才未満・学生証提示 ※学生の方は現地決済にていったんお申込みください。当日割引額にて受付 https://www.tpac.info/events/detail/id=1014&state=off', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51060', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60414, '2026-10-16', '福岡県', '福岡伝統芸能フェスタ 福芸-FUKUGEI-2026 ＜ワークショップ＞ 申し込み締め切り１０月１１日（日）まで', '大濠公園能楽堂', '14:00', '大濠公園能楽堂 伝統芸能体験ワークショップ ★能面をつけてみよう！未知の世界へ 〜能面体験〜 12：30 受付 / 13：00 〜 14:00（予定） 参加費：無料（事前申込必須） 定員：30名程度 対象：小学生以上（大人の方もご参加いただけます） ★高座にあがってみよう！落語家体験 ●参加無料 事前お申し込みはこちら https://www.fukugei.com/ws/index.html 【１０月１１日（日）まで】 https://www.fukugei.com/index.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51805', 0, 0);
