INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60425, '2026-10-17', '兵庫県', '有馬能楽堂 能公演《土蜘蛛》', '三田屋本店', '17:30', '17時半 三田屋本店 兵庫県三田市武庫が丘7-5 能《土蜘蛛 つちぐも》 僧・土蜘蛛 大槻裕一 源頼光 大槻文藏 胡蝶 上野雄介 従者 稲本幹汰 独武者 福王知登 従者 矢野昌平 独武者の下人 善竹隆平 笛 野口亮 小鼓 成田奏 大鼓 山本寿弥 太鼓 前川光範 後見 赤松禎友・上野雄三・武富康之 地謡 上田拓司・山本博通・浦田保親・齊藤信輔・水田雄晤・山田薫 ●特別さじき席（公演の日だけの特別なお食事付き） 受付/16:30〜 開演/17:30 終演後お食事 能舞台に近いお席でご鑑賞いただきます。 終演後には公演の日だけの「神戸ビーフコース」をお召し上がりいただきます。 料金/25,000円（さじき席鑑賞代、お食事代を含みます） レストラン席（公演の日だけの特別なお食事付き） 受付/16:30〜 開演/17:30 終演後お食事 レストラン内（能舞台正面）でご鑑賞いただきます。 終演後には公演の日だけの「黒毛和牛ヘレステーキコース」または 「神戸ビーフコース」をお召し上がりいただきます。 料金/黒毛和牛ヘレコース 15,700円（レストラン席鑑賞代、お食事代を含みます） 神戸ビーフコース 23,500円（レストラン席鑑賞代、お食事代を含みます） レストラン席（後日ご利用可能なお食事券付き） 受付/17:00〜 開演/17:30 レストラン内（能舞台正面）でご鑑賞いただきます。 公演日翌日以降から1年間使用可能な「黒毛和牛ロースステーキコース食事券」または 「黒毛和牛ヘレステーキコース食事券」付き ※当日のお食事はございません 料金/黒毛和牛ロース 12,000円（レストラン席鑑賞代、お食事券代を含みます） 黒毛和牛ヘレ 13,800円（レストラン席鑑賞代、お食事券代を含みます） ※入場は小学生以上です。 ※公演中の撮影・録音・録画はご遠慮ください。 ※事情により内容変更、延期、中止の場合がございます。 ※ご購入後のお客様のご都合によるキャンセルは、受付致しかねます。あらかじめご了承ください。 お問い合わせ先 三田屋本店―やすらぎの郷― 〒669-1544 兵庫県三田市武庫が丘7-5 フリーダイヤル 0120-711-863 （10:00〜18:00） 電話番号 079-564-4151 (代) FAX番号 079-564-4152 ウェブサイト https://sandaya-honten.co.jp/ 予約はこちらから https://sandaya.peatix.com/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50966', 0, 0);
