INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60473, '2026-10-19', '東京都', '第15回 喜多流職分 中村邦生の謡曲講座『龍田』', '市川房枝記念婦選会館', '10:30', '●場所 市川房枝記念婦選会館 東京都渋谷区代々木2-21-11 ・JR新宿駅南口・代々木駅西口徒歩10分 ・大江戸線A1出口徒歩5分 ●日時（全６回） 10月 5日（月）10:30〜12:00 10月19日（月）10:30~12:00 11月 16日（月）10:30〜12:00 11月30日（月）15:30〜17:00 12月 7日（月）10:30~12:00 12月21日（月）15:00~16:30 ●講座内容 ・謡の実演 ・謡曲の美しい日本語を声に出して楽しむ ・能の話、能楽師の仕事、舞台裏話など ●講師 能楽師シテ方喜多流職分 中村邦生 ●受講料 一括受講 ￥12,000（全6回） 単回受講 ￥3,000（1回） ※別途テキスト代2,100円 喜多流謡本『龍田』 ※喜多流謡本をお持ちの方はお持ちください。 単回受講の方はご相談ください。 ※講座内容の録音配信での受講もご相談に応じます。 ■お問合せ 中村邦生の会事務所 TEL 03-5310-5690', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51758', 0, 0);
