INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60479, '2026-10-21', '大分県', '宇佐神宮風除報賽祭 宇佐神宮御神能', NULL, '05:00', '正午より１５時３０分（終演予定） ※正午より、能楽殿にて神事があります。 ※受付は１０時からです。 【場所】 宇佐神宮 能楽殿 １２時３０分 素揺 【 神歌（かみうた）】 仕舞 【 賀茂（かも） 】 【 巻絹 キリ（まきぎぬ） 】 【 松風（まつかぜ） 】 【 融（とおる） 】 【 野守（のもり） 】 １３時００分頃 解説 武田友志 舞囃子【 西王母（せいおうぼ）】武田文志 笛 森田光次 小鼓 飯冨孔明 大鼓 白坂保行 太鼓 吉谷潔 狂言 【 悪坊（あくぼう）】茂山忠三郎 中島清幸 秋吉英二 １４時３０分頃 能 【 田村（たむら）】武田友志 飯冨雅介 岡充 河原康生 笛 森田光次 小鼓 飯冨孔明 大鼓 白坂保行 地頭 武田文志 １５時３０分頃 終了 ●【入場料金】 前売券 ２,５００円 当日券 ３,０００円 （全席自由・中学生以下無料） ※未就学児童は入場できません 宇佐神能会事務局（宇佐神宮内） TEL：0978-37-0001 一般社団法人 宇佐市観光協会 TEL：0978-37-0202 http://www.usajinguu.com/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#49276', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60480, '2026-10-21', '東京都', '野村萬斎 還暦記念「狂言ござる乃座72nd」第一日目 ※情報追加', '国立能楽堂', '18:00', '18時15分 国立能楽堂 ★一調「貝尽し」野村萬斎 太鼓 観世結子 ★舞囃子「高砂」宝生和英 ★狂言 末廣かり 野村万作・野村又三郎・石田幸雄 ★狂言 庵の梅 野村萬斎・野村太一郎・内藤連・石田淡朗・中村修一・飯田豪・野村裕基 ★一調「屋島」「女郎花」 観世喜正 小鼓 大倉源次郎、片山九郎右衛門 大鼓 亀井広忠 ★獅子 双之舞・千尋谷落・還暦之式 野村萬斎・野村裕基 ★半能「石橋 大獅子」 観世銕之丞・観世淳夫・福王和幸ほか ●Ｓ席15,000円 Ａ席10,000円 B席8,000円 C席5,000円 学生席3,000円 一般前売発売日 2026年9月25日（金）10:00 チケットぴあ セブンイレブンでも取扱い有 カンフェティ TEL：050-3092-0051（電話受付時間 平日10：00〜17：00） ファンクラブyoiya2会員先行予約実施！【7月上旬予定】 現在ファンクラブ会員でない方で、会員先行販売への申込みをご希望の方は、申込期限までに新規会員登録の手続きを完了のうえお申込みください。 ※ 学生券のご予約は一般発売日11：00より万作の会 （TEL：03-5981-9778）にて承ります。 ※ 一般発売で売切の場合、キャンセル待ちを万作の会 （TEL：03-5981-9778）にて承ります。 ■万作の会 ０３−５９８１−９７７８ https://mansaku.co.jp/ ／ 時間：17時30分開場 18時15分開演 21時終演予定 場所：国立能楽堂 ★一調「貝尽し」野村萬斎 太鼓：観世結子 ★舞囃子「高砂」宝生和英 笛：竹市学 小鼓：大倉伶士郎 大鼓：柿原弘和 太鼓：金春惣右衛門 地頭：辰巳満次郎 ★狂言「末廣かり」 果報者：野村万作 太郎冠者：野村又三郎 すっぱ：石田幸雄 笛：竹市学 小鼓：大倉伶士郎 大鼓：柿原弘和 太鼓：観世結子 ★狂言「庵の梅」 老尼：野村萬斎 立衆：野村太一郎・内藤連・石田淡朗・中村修一・飯田豪・野村裕基 笛：松田弘之 小鼓：大倉源次郎 大鼓：亀井広忠 太鼓：林雄一郎 ★一調「屋島」観世喜正 小鼓：大倉源次郎 「女郎花」片山九郎右衛門 大鼓：亀井広忠 ★狂言「獅子 双之舞・千尋谷落・還暦之式」 白獅子：野村萬斎 赤獅子：野村裕基 笛：竹市学 小鼓：大倉伶士郎 大鼓：柿原弘和 太鼓：金春惣右衛門 地頭：高野和憲 ★半能「石橋 大獅子」 シテ（白/親獅子）：観世銕之丞 ツレ（赤/子獅子）：観世淳夫 ワキ（寂昭法師）：福王和幸 笛：松田弘之 小鼓：大倉源次郎 大鼓：亀井広忠 太鼓：林雄一郎 地頭：観世喜正 ●料金 S席：15,000円 A席：10,000円 B席：8,000円 学生席：3,000円 ■一般前売発売日 2026年9月25日（金）10:00〜 ■お求め先 ・チケットぴあ https://t.pia.jp/pia/event/event.do?eventBundleCd=b2669673 Pコード：543-967 セブンイレブンでも取扱い有 ・カンフェティ https://www.confetti-web.com/ TEL：050-3092-0051（平日10時〜17時受付） ・ファンクラブyoiya2会員《2次》先行予約実施！【有料WEB会員限定：8/7（金）11:00〜8/23（日）23:59】 https://fan.pia.jp/yoiya2/news/detail/442/ 現在ファンクラブ会員でない方で、会員先行販売への申込みをご希望の方は、申込期限までに新規会員登録の手続きを完了のうえお申込みください。 ※学生券のご予約は一般発売日11:00より万作の会（TEL：03-5981-9778）にて承ります。 ※一般発売で売切の場合、キャンセル待ちを万作の会（TEL：03-5981-9778）にて承ります。 ■お問い合わせ先 万作の会 TEL：03-5981-9778（平日10時〜17時受付） https://mansaku.co.jp/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50614 ／ https://nohgaku.f