INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60503, '2026-10-24', '京都府', '杉市太郎五十回忌追善 二代目杉市太郎襲名披露能', '京都観世会館', '12:00', '時間：12時開場 13時開演 17時半頃終了予定 場所：京都観世会館 ★舞囃子「清経」 平清経の霊：浦田保浩 笛：鈴木麻里 小鼓：林吉兵衛 大鼓：石井景之 地頭：井上嘉介 ★能「檜垣 蘭拍子」 老女/檜垣女の霊：片山九郎右衛門 僧：宝生欣哉 間 所の者：茂山七五三 笛：杉市太郎（杉市和改め） 小鼓：大倉源次郎 大鼓：河村大 後見：大槻文藏、他 地頭：観世銕之丞 副地頭：浅井文義 ★狂言「石神」 男：茂山千五郎 仲人：茂山茂 女：茂山逸平 笛：相原一彦 小鼓：吉阪一郎 ★一調一管「龍田」 謡：大槻文藏 笛：左鴻泰弘 太鼓：前川光長 ★一管「豊後下り端」 笛：森田保美 ★半能「石橋 さん猊之式」 白獅子：金剛永謹 さん獅子：宇高竜成 猊獅子：金剛龍謹 寂昭法師：宝生朝哉 笛：杉信太朗 小鼓：曾和鼓堂 大鼓：谷口正壽 太鼓：前川光範 後見：廣田幸稔、他 地頭：今井清隆 副地頭：松野恭憲 ●料金 全席指定席 S正面席：18,000円 A正面席：17,000円 脇正面席：15,000円 中正面席：13,000円 2階1列目：9,000円 その他2階席：6,000円 ※満席の場合、正面席及び脇正面席の補助席を販売する場合がございます ■チケット発売日 一般発売：8月29日（土）10:00〜 ※先行発売で売り切れの場合もございます ■お申込み 杉信の会事務局 メール：sugishin.jimukyoku＠gmail.com ＠を@に変えて送信 お名前・郵便番号・ご住所・電話番号・枚数をお書き添えの上、メールでお申し込みください ■お問合せ 受付時間：全日10:00〜18:00 電話：090-3326-8806 留守番電話の際はメッセージをお願いします 担当者より折り返しご連絡申し上げます http://www.kyoto-kanze.jp/show_info/#202610', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51411', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60504, '2026-10-24', '京都府', '杉市太郎五十回忌追善能 二代目杉市太郎襲名披露能 当日券あるそうです。１１時半から販売', '京都観世会館', '13:00', '13時 京都観世会館 ★舞囃子 清 経 浦田 保浩 ★能 檜 垣 蘭拍子 片山九郎右衛門 ★狂言 石 神 茂山千五郎 ★一調一管 龍 田 大槻 文藏 ★一管 豊後下り端 森田 保美 ★能 石 橋 さん猊之式 金剛 永謹 一般発売８／２９（土）午前１０時 ●全席指定 Ｓ正面席 ￥18,000 Ａ正面席 ￥17,000 脇正面席 ￥15,000 中正面席 ￥13,000 ２階１列目 ￥9,000 その他２階席 ￥6,000 ※先行発売で売り切れの場合もございます。 ■お申込み 杉信の会事務局 メール sugishin.jimukyoku☆gmail.com ☆を＠に変えて送信 https://x.com/sugishin_no_kai http://www.kyoto-kanze.jp/show_info/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50483', 0, 0);
