INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60507, '2026-10-24', '兵庫県', '第50回特別編能のことばを読んでみる会《井筒》', NULL, '14:00', '令和8年（2026年）10月24日(土)14時開始 会場：芦屋能舞台（兵庫県芦屋市松ノ内町10-16） ［阪急電鉄神戸線「芦屋川」駅から東へ3分 JR神戸線「芦屋」駅から北へ10分］ 能のことば（詞章・謡曲）を読みとく勉強会 テーマ曲：《井筒》 ※今回は特別編として謡の披露もあり ゲスト：長山耕三（能楽師シテ方観世流） 江崎欽次朗（能楽師ワキ方福王流） 進行役：朝原広基（能楽研究家・能楽と郷土を知る会代表） ●参加費：2,500円 ■申込・問合先 能楽と郷土を知る会 TEL：090-3969-1608（朝原） E-mail： info@nohgaku-kyodo.com https://nohgaku-kyodo.com/repertoire/yondemiru-idutsu20261024', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51240', 0, 0);
