INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60510, '2026-10-24', '奈良県', '興福寺塔影能', NULL, '15:30', '受付15時半 法要16時半 16時45分開演 興福寺中金堂 雨天 春日野国際フォーラム能楽ホール ★狂言 雁礫 茂山忠三郎 ★能 鉢木 辰巳満次郎 ●奉納陪観 ７０００円 定員制 先着500名 申し込みはがき付きのご案内が配布されていて そちらで申し込みということになっております。 申し込みはがき 興福寺塔影能 倍観（ ）名、申し込みます。と記入し 郵便番号・住所・氏名・電話番号を明記の上、下記まで。 ６３０−８２１３ 奈良市登大路町４８ 興福寺々務所 塔影能係 ご案内が手に入らない方は下記にお問合せ下さい ■興福寺寺務所 電話（０７４２）２２−７７５５（9時から17時） http://www.kohfukuji.com/ https://www.kohfukuji.com/event/toueinou/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50990', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60511, '2026-10-24', '愛知県', 'ふらっと能楽堂 第2回「お金とお米の話」', '豊田市能楽堂', '14:00', '開演 14:00 開場 13:30 豊田市能楽堂 狂言の話もあるようです。 出 演 講師／柳沢新治（能楽ジャーナリスト） 司会／国井雅比古（元NHKエグゼクティブアナウンサー） ●入場料 1,000円（全席自由） ※8月15日（土）10時より発売開始 ■問合せ 豊田市コンサートホール・能楽堂事務室 0565-35-8200 ※友の会割引対象事業ではありません。 ※未就学児入場不可 https://www.t-cn.gr.jp/15443/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51542', 0, 0);
