INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60513, '2026-10-24', '新潟県', 'のぞいてみよう 能の世界〜半能「黒塚」（喜多流）', 'りゅーとぴあ新潟市民芸術文化会館 能楽堂', '15:00', '15:00開演（14:45開場) りゅーとぴあ新潟市民芸術文化会館 能楽堂 半能 喜多流 「黒塚」 ●全席自由 500円 ※この公演は「さわってみよう能の世界」の一部を公開します。 当日の進行状況により、開場および開演時間は若干遅くなる可能性があります。 ※未就学のお子様（乳幼児含む）もご覧になるため、本番中も客席に人が出入りする可能性があります。 チケット発売日：8/27（木） 10時 りゅーとぴあ ・オンライン・チケット ・電話 025-224-5521 ・窓口（りゅーとぴあ2階） ※発売初日は取り扱いなし お問い合わせ りゅーとぴあチケット専用ダイヤル TEL 025-224-5521（10-18時/休館日除く） https://www.nohgaku.or.jp/performance/nozoitemiyou_nohnosekai2026', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51379', 0, 0);
