INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60517, '2026-10-24', '東京都', '誠翔会特別公演 Kyogen Lounge Vol.78', 'セルリアンタワー能楽堂', '14:00', '14:00（13:00開場）セルリアンタワー能楽堂 終演時間 16:00頃 狂言「盆山」 盗人：田中惇之 亭主：冨田昌美 狂言「神鳴」 神鳴：大藏基誠 医師：山本則秀 狂言「鬮罪人」 太郎冠者：大藏康誠 主人：大藏基誠 客：大藏教義 客：吉田信海 客：田中惇之 客：冨田昌美 客：上田圭輔 笛：平野史夏 ●全席指定席 S席 10,000円／A席 8,000円／B席 6,000円／C席 5,000円 ※ドリンクチケットはついておりません。 ※未就学児の御入場は御遠慮頂いております。 ◎子ども無料ご招待 18歳以下のお子様はB席相当【無料】でご入場いただけます。 さらに、ご引率の保護者の方はB席相当 通常6,000円 → 半額3,000円（子ども2名につき1名まで） ※子ども無料席のお申込み、ご入場は、子どもの年齢にかかわらず引率者のご同伴、引率者様用のチケットのご購入をお願いします。 お問合せ https://www.kyogen.info/ https://x.com/nari0303 https://www.ceruleantower-noh.com/lineup/2026/20261024.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51053', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60518, '2026-10-24', '東京都', '野村萬斎 還暦記念「狂言ござる乃座72nd」第二日目 ※情報追加', '国立能楽堂', '13:00', '13時 国立能楽堂 ★翁 父尉延命冠者之式・田歌節 観世清和・観世三郎太・野村萬斎・野村裕基ほか ★連吟「菊之舞」 石田幸雄・野村遼太・月崎晴夫・竹山悠樹・破石晋照・岡聡史・福田成生・金澤桂舟・松川美韻希 ★狂言 二人大名 野村万作・三宅近成・三宅右矩 ★狂言 庵の梅 野村萬斎・野村太一郎・内藤連・石田淡朗・中村修一・飯田豪・野村裕基 ●Ｓ席17,000円 Ａ席12,000円 B席10,000円 C席7,000円 学生席4,000円 一般前売発売日 2026年9月25日（金）10:00〜 チケットぴあ セブンイレブンでも取扱い有 カンフェティ TEL：050-3092-0051（電話受付時間 平日10：00〜17：00） ファンクラブyoiya2会員先行予約実施！【7月上旬予定】 現在ファンクラブ会員でない方で、会員先行販売への申込みをご希望の方は、申込期限までに新規会員登録の手続きを完了のうえお申込みください。 ※ 学生券のご予約は一般発売日11：00より万作の会 （TEL：03-5981-9778）にて承ります。 ※ 一般発売で売切の場合、キャンセル待ちを万作の会 （TEL：03-5981-9778）にて承ります。 ■万作の会 ０３−５９８１−９７７８ https://mansaku.co.jp/ ／ 時間：12時15分開場 13時開演 16時30分終演予定 場所：国立能楽堂 ★「翁 父尉延命冠者之式・田歌節」 翁：観世清和 千歳：観世三郎太 三番叟：野村萬斎 面箱：野村裕基 笛：松田弘之 頭取：飯田清一 胴脇：住駒匡彦 手先：成田達志 大鼓：亀井広忠 地頭：岡久広 ★連吟「菊之舞」 石田幸雄・野村遼太・月崎晴夫・竹山悠樹・破石晋照・岡聡史・福田成生・金澤桂舟・松川美韻希 ★狂言「二人大名」 通りの者：野村万作 大名：三宅近成・三宅右矩 ★狂言「庵の梅」 老尼：野村萬斎 立衆：野村太一郎・内藤連・石田淡朗・中村修一・飯田豪・野村裕基 笛：松田弘之 小鼓：成田達志 大鼓：亀井広忠 太鼓：林雄一郎 ●料金 S席：17,000円 A席：12,000円 B席：10,000円 学生席：4,000円 ■一般前売発売日 2026年9月25日（金）10:00〜 ■お求め先 ・チケットぴあ https://t.pia.jp/pia/event/event.do?eventBundleCd=b2669673 Pコード：543-968 セブンイレブンでも取扱い有 ・カンフェティ https://www.confetti-web.com/ TEL：050-3092-0051（平日10時〜17時受付） ・ファンクラブyoiya2会員《2次》先行予約実施！【有料WEB会員限定：8/7（金）11:00〜8/23（日）23:59】 https://fan.pia.jp/yoiya2/news/detail/442/ 現在ファンクラブ会員でない方で、会員先行販売への申込みをご希望の方は、申込期限までに新規会員登録の手続きを完了のうえお申込みください。 ※学生券のご予約は一般発売日11:00より万作の会（TEL：03-5981-9778）にて承ります。 ※一般発売で売切の場合、キャンセル待ちを万作の会（TEL：03-5981-9778）にて承ります。 ■お問い合わせ先 万作の会 TEL：03-5981-9778（平日10時〜17時受付） https://mansaku.co.jp/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50615 ／ https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51508', 0, 0);
