INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60523, '2026-10-24', '香川県', '能楽体験会＜「能と雅楽」公演の事前講習会＞', NULL, '10:00', '11月29日（日）に開催の「能と雅楽」に先駆け、能「経政」の事前講習会を開催します。 講師は香川県出身の能楽師、伶以野陽子氏。 事前知識を深めておくことで、本公演をより深くお楽しみいただけます。 能が初めての方も分かりやすく解説しますので是非お気軽にご参加ください。 【日程】2026年10月24日（土） 【時間】10時30分〜12時 【場所】ユープラザうたづ視聴覚室 【参加費】無料（※事前予約制） ※9月1日（火）から受付開始 【定員】90名 【申込先】0877-49-8020(9時〜21時/電話又は事務所にて) ※月曜休館（祝日の場合は翌日） 【内容】 ・経政のあらすじ ・謡体験 ・能面/装飾体験（希望者） 【主催/お問い合わせ】ユープラザうたづ（0877-49-8020） ・駐車台数には限りがありますので公共交通機関をご利用ください。周辺施設及び月極駐車場への無断駐車は禁止です。また周辺道路は駐車禁止です。 https://uplaza-utazu.jp/uplaza_post/5166/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51506', 0, 0);
