INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60529, '2026-10-25', '大阪府', '五世 茂山忠三郎芸歴４０周年記念公演 忠三郎狂言会', '大槻能楽堂', '14:00', '14時 大槻能楽堂 ★狂言 柑子 茂山良倫 茂山忠三郎 ★狂言 酢薑 善竹隆司 善竹忠亮 ★一管 獅子 ★狂言 釣狐 茂山忠三郎 善竹隆平 笛 斉藤敦 ●S.S 正面指定席 ７，０００円 S. 脇正面・中正面指定席 ６，０００円 A. 次世代応援シート ５，０００円 〈お席の指定はできません〉 ※当日 ７，０００円 学生（学生席） ２，５００円 ※学生のみ当日３，５００円 ■忠三郎狂言会事務所 http://chuzaburo.com FAX ０７０− ４３２−６６５５ https://chuzaburo.com/2026/06/14/%e4%bb%a4%e5%92%8c8%e5%b9%b4%e5%ba%a6%e3%80%80%e5%bf%a0%e4%b8%89%e9%83%8e%e7%8b%82%e8%a8%80%e4%bc%9a/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51044', 0, 0);
