INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60531, '2026-10-25', '大阪府', '阿倍野区能楽講座「能への誘(いざな)い」能面と能装束の魅力にせまる', '阿倍野図書館 多目的室', '14:00', '日時：10月25日（日曜日） 14時〜16時 定員：50名（事前申込制・先着順） 講師：井戸 良祐（いど りょうすけ）さん 観世流 能楽師（阿倍野区在住 重要無形文化財保持者） 能で使われる面(おもて)や能装束に込められた意味や背景から、当時の人々の思いに触れる。 重要無形文化財保持者である井戸 良祐さんが、実際の面や装束、道具とともにくわしく解説！ 場所 阿倍野図書館 多目的室（大阪市阿倍野区阿倍野筋4-19-118） 申込 阿倍野図書館へ来館または電話（06-6656-1009）による申込。 10月6日（火曜日）10時から受付開始（事前申込制・先着順。開館時間内のみ受付） 参加無料 https://www.city.osaka.lg.jp/abeno/page/0000686205.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51717', 0, 0);
