INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60534, '2026-10-25', '東京都', 'ふらっと狂言会♭8', '国立能楽堂', '11:00', '11:00開演 国立能楽堂 解説 野村万之丞 狂言「狐塚」 野村眞之介 石井康太 野村拳之介 狂言「茶壷」小笠原弘晃 河野佑紀 野村万之丞 三兄弟トーク チケット 8月5日（水）一般発売 ●指定席 4,000円（70席上限：正面席中央） 自由席 一般 3,000円／Uｰ29 2,000円（29歳以下） ※今回より一部指定席を設けます。販売は「ヨロズチケット（萬狂言）」（以下のWeb購入含む）のみでのお取り扱い ※入場は5歳以上 チケットぴあ［Pコード：544-411］ イープラス ※イープラスでは8/6（木）より取扱い開始 ヨロズチケット ※インターネット購入〈ヨロズチケット〉について、予約後、後日お近くのセブンイレブンで支払いとチケット発券ができます（手数料等は別途必要です）。 ※この公演は、〈ヨロズチケット〉からお申込みでクレジット決済分に限り、チケットレス入場（れすQ）がご利用いただけます。 公演当日はQRコードをかざしてご入場となり、QRコードの発行手数料は紙チケットよりもお得です。 ◎お電話でチケットお申込みの場合 萬狂言 0120-807-305（平日11〜18時） https://yorozukyogen.jp/index.html#syusai', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50524', 0, 0);
