INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60536, '2026-10-25', '東京都', 'セルリアンタワー能楽堂開場二十五周年記念 定期能十月−観世流−', 'セルリアンタワー能楽堂', '13:00', 'セルリアンタワー能楽堂 ＜第一部＞ 13:00開演（12:30開場） 解説：竹内晶子 仕舞「井筒」 関根知孝 地頭：岡久広 狂言「富士松」 太郎冠者：野村太一郎 主：高野和憲 後見：深田博治 能「屋島」 漁翁／源義経の霊：関根祥丸 漁夫：久田勘吉郎 旅僧：宝生常三 浦人：松川美韻希 笛：松田弘之 小鼓：飯田清一 大鼓：亀井広忠 後見：武田尚浩、坂井音隆 地頭：岡久広 ＜第二部＞16:30開演（16:00開場） 解説：竹内晶子 仕舞「忠度」 観世三郎太 地頭：関根知孝 狂言「二九十八」 男：野村太一郎 乙：月崎晴夫 後見：高野和憲 能「龍田 移神楽」 巫女／龍田明神：坂口貴信 旅僧：宝生常三 里人：深田博治 笛：松田弘之 小鼓：飯田清一 大鼓：亀井広忠 太鼓：小寺真佐人 後見：武田尚浩、関根祥丸 地頭：関根知孝 チケット先行販売 年会費無料 オンラインチケット購入 ●各部 S席（正面） 10,000円 A席（脇正面） 8,000円 B席（中正面） 6,000円 学生席（座敷・自由） 4,000円 ※学生席はセルリアンタワー能楽堂のみにて取り扱います。購入の際に学生証をご提示ください。 ※未就学児の入場はご遠慮ください。 ※都合により公演の一部(出演者･曲目等)を変更する場合がございます。 ※公演中止、または主催者がやむを得ないと判断する場合以外のチケットの払い戻しはいたしません。 チケット発売日 MY Bunkamura先行発売 2026/7/24(金)10:00&#12316;2026/7/24(金)23:59 先着制 MY Bunkamuraについて 一般発売 2026/7/25(土) 10:00 チケット取扱い チケットガイド Bunkamuraでのお申込み お電話 Bunkamuraチケットセンター（10:00〜15:00） 03-3477-9999 チケットカウンター 東急シアターオーブ/Bunkamuraチケットカウンター＜渋谷ヒカリエ2F 11:00〜18:00＞ インターネット オンラインチケット購入 ※Bunkamuraでの一般発売日＜7/25(土)＞は、Bunkamuraチケットセンター電話およびオンラインチケットMY Bunkamura（PC、スマートフォン）での受付となります。東急シアターオーブ／Bunkamuraチケットカウンター （店頭）での販売はございません。 ※電話または店頭でお申込みの場合は、ご利用前に必ず「Bunkamura チケット販売サービス利用規約」 &#9654; https://www.bunkamura.co.jp/ticketguide/t_kiyaku.html をご一読ください。 ※営業時間の最新情報は&#9654; https://www.bunkamura.co.jp/topics/3491.html をご確認ください。 セルリアンタワー能楽堂でのお申込み お電話 03-3477-6412 ＜平日10:00〜18:00／土日祝14:30〜17:30＞ ■お問合せ セルリアンタワー能楽堂 03-3477-6412 ＜平日10:00〜18:00／土日祝14:30〜17:30＞ ※営業時間は変更になる可能性がございます。何卒ご了承ください。 https://www.ceruleantower-noh.com/lineup/2026/20261025.html https://www.ceruleantower-noh.com/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#50654', 0, 0);
