INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60542, '2026-10-25', '東京都', '第10回「未来につながる伝統」能公演 能「綾鼓」', '宝生能楽堂', '14:00', '14:00開演 13:00開場 宝生能楽堂 能「綾鼓」の世界（演目のご案内） 解説：佐野 登 案内人：小山龍介［名古屋商科大学 教授、京都芸術大学特任准教授］ スペシャルトーク 佐野 登［能楽師シテ方・宝生流］ ゲスト：別所哲也［俳優／国際短編映画祭代表］ 司会 ：本田勝之助［内閣府クールジャパン地域プロデューサー］ 【舞囃子】天 鼓 宝生和英 地謡： 和久荘太郎 ��橋憲正 内藤飛能 辰巳和磨 笛 熊本俊太郎 小鼓 観世新九郎 大鼓 柿原弘和 【狂 言】萩大名 シテ[大名] 野村萬斎 アド[太郎冠者]金澤桂舟 小アド[茶屋]石田淡朗 後見 野村裕基 【 能 】綾 鼓 前シテ[庭掃きの老人]・後シテ[老人の怨霊] 佐野 登 ツレ[女御] 渡邊隆士 ワキ［臣下］ 福王和幸 間[従者] 石田幸雄 笛 熊本俊太郎 小鼓 観世新九郎 大鼓 柿原弘和 太鼓 桜井 均 後見：宝生和英 和久荘太郎 地謡：今井泰行 辰巳満次郎 山内崇生 小倉伸二郎 ��橋憲正 内藤飛能 辰巳大二郎 辰巳和磨 ●S席［正面］11,000円 A席［脇正面］8,800円 B席［中正面］7,700円 自由席［脇正面後方］5,500円 学生［自由席］3,300円（全て税込） チケットの購入方法 １．WEBでのご購入（カンフェティチケットセンター） http://confetti-web.com/@/miraiden2026 （1）予約：パソコン・スマートフォンから専用サイトにアクセス（クレジットカード可） （2）お支払い＆受け取り（ファミリーマート） 払込番号をお持ちのうえ、予約有効期間内にファミリーマート店頭レジでお受け取りください。 ２．窓口でのご購入（宝生能楽堂：公益社団法人宝生会事務局） ※お支払は現金のみ（火〜日曜日 10:00-17:00） 東京都文京区本郷1-5-9 TEL：03-3811-4843 ３．メール申込（一般社団法人未来につながる伝統事務局） ※申込後、銀行振込（送料600円がかかります） お名前、ご住所、電話番号、希望席種、購入枚数をメールで送信 E-mail：shihoukai202@gmail.com 鑑賞前の能楽講座 日時：2026年9月27日(日)14:00〜16:00 場所：しらい荘舞台（しらいそうぶたい） 文京区本郷1-5-7 宝生ハイツ202号室 申込方法：メールで「shihoukai202@gmail.com」宛にお名前・連絡先送信 募集人数：先着15名様 https://www.nohgaku.jp/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51656', 0, 0);
