INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60565, '2026-10-30', '滋賀県', '第8回 能楽大連吟 近江DE謡隊 能 竹生島 初回オリエンテーション', NULL, '15:00', '草津市立草津クレアホール活動室 https://kusatsu-art.center/creahall 15時と17時 ●謡隊参加費 一般12000円 学生（大学生以下）6000円 親子（小学生）13000円 お稽古には扇が必要 お持ちでない方はオリエンテーションの際にお申し込み可能 全体稽古 2027年2月4日 草津クレアホール 15時と19時 本番公演 第8回 能楽大連吟 近江DE謡隊 能 竹生島 2027年2月14日(日) 14時 草津市立草津クレアホール https://kusatsu-art.center/creahall 解説 能・竹生島と大連吟について 吉浪壽晃 大連吟公演 能 竹生島 浦部幸裕 田茂井廣道 岡充 有松遼一 茂山千之丞 笛 鈴木麻里 小鼓 成田奏 大鼓 河村凛太郎 太鼓 中田一葉 地謡 吉浪壽晃 宮本茂樹 河村浩太郎 鷲尾世志子 寺澤拓海 近江DE謡隊参加者 ●当日鑑賞券 一般1000円 大学生以下500円 親子チケット（小学生）1200円 チラシがこちらに https://x.com/oumideutaitai/status/2111291308472184867 申し込みはチラシのはがきかメールかFAXで ■能楽大連吟 近江DE謡隊 事務局 FAX０７５−５８１−０６９４（吉浪方） メール oumideutaitai☆gmail.com ☆を＠に変えて送信 https://dairengin.com/ https://x.com/oumideutaitai/status/2111291308472184867', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51851', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60566, '2026-10-30', '神奈川県', 'はじめての能 平家物語の世界を 鎮魂の能「清経」', NULL, '12:00', '久良岐能舞台 正午の部 12時から13時半 午後の部 14時半から16時 ワークショップ 能鑑賞「清経」加藤眞悟 梅若千音世 梅村昌功 笛 栗林祐輔 小鼓 森貴史 大鼓 大倉栄太郎 地頭 梅若志長 ●参加費5000円 各回100名 ■明之會 ０４５−４８１−８７０４ https://x.com/katoshingo55/status/2088953209947873692', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51655', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60567, '2026-10-30', '茨城県', '第27回土浦薪能', '土浦城址本丸', '17:00', '土浦城址本丸（亀城公園） 雨天時は、クラフトシビックホール土浦（土浦市民会館） 大ホール 開場 17時00分 開演 18時00分 終演（予定） 20時00分 ★狂言「二人袴（ふたりばかま）」 野村万作（人間国宝） 野村萬斎 月崎晴夫 飯田豪 ★能 「清経（きよつね）」 観世銕之丞 小早川康輝 舘田善博 笛 熊本俊太郎 小鼓 飯冨孔明 大鼓 柿原孝則 地頭 清水寛二 ●全席指定 未就学児の入場はご遠慮ください SSS席/10,000円 SS席/8,000円 S席/6,000円 A席/4,000円 一般販売日 窓口販売 7月28日 火曜日 9時から 販売所 ・教育委員会文化振興課 ・クラフトシビックホール土浦 ・亀城プラザ ※販売所ごとに、お取り扱いしている席が異なります。 各施設の休館日・営業時間はお問い合わせください。 チケット代金の支払 窓口販売受付時に販売所で直接お支払いください。 チケットの電話受付・郵送につきましては、文化振興課分のみ対応可能です。 下記銀行口座（チケット代金専用）へ1週間以内にお振込ください。 振り込みが確認でき次第郵送いたします。 ※書留送料はお客様のご負担となります。 「常陽銀行 土浦市役所出張所 普通 1023312 土浦薪能（座席券代）事務局長 佐賀憲一 ﾂﾁｳﾗﾀｷｷﾞﾉｳ(ｻﾞｾｷｹﾝﾀﾞｲ)ｼﾞﾑｷﾖｸﾁﾖｳ ｻｶﾞｹﾝｲﾁ」 薪能倶楽部への入会 薪能倶楽部にご加入いただきますと、先行販売にて、チケットの購入が可能です。 個人会員会費は2,000円です。購入するチケットの内1枚のみ1,000円引きで購入いただけます。 会費につきましては、事務局で直接お支払いいただくか、または下記銀行口座（会費専用）へお振込ください。 「常陽銀行 土浦市役所出張所 普通 1022691 土浦薪能（会費）事務局長 佐賀憲一 ﾂﾁｳﾗﾀｷｷﾞﾉｳ(ｶｲﾋ)ｼﾞﾑｷﾖｷﾁﾖｳ ｻｶﾞｹﾝｲﾁ」 ※チケット代金の支払い先とは口座が異なりますのでご注意ください。 ■お問い合わせ先 土浦薪能倶楽部事務局（土浦市教育委員会 文化振興課） 電話 029‐893-5505 https://www.city.tsuchiura.lg.jp/kanko-bunka-sports/news/page021604.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51243', 0, 0);
