INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60591, '2026-10-31', '熊本県', '能楽ワークショップ 日本の伝統文化を体験してみませんか? 定員20名程度', NULL, '10:00', '午前10時30分（受付は午前１０時） 天草市民センター 剣道場 〒863-0033 熊本県天草市東町3 能楽師の狩野了一氏のほか喜多流の能楽師（狩野祐一・大島衣恵）が 仕舞や謡（うたい）に加えて面の付け方やすり足など 能楽の基本を体験できます。 ●500円 高校生以下100円 対象：小学生以上、定員20名程度（定員に達し次第締め切り） お申込み：9月10日から10月20日に電話、またはFAX,Eメールで 参加の際は足袋や白い靴下をご持参ください ワークショップの様子を観覧も可能です。（申し込み不要） ■お問い合わせ 天草市民センター 電話：0969-22-4125 Fax：0969-22-5475 Eメール：center@amakusa-cc.com https://amakusa-cc.com/2026/08/27/%E8%83%BD%E6%A5%BD%E3%83%AF%E3%83%BC%E3%82%AF%E3%82%B7%E3%83%A7%E3%83%83%E3%83%97/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51674', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60592, '2026-10-31', '石川県', '能のいろはを楽しく学べる 能楽体験ワークショップ 「シテ、ワキの違いと役割 VOL.2」', '石川県立能楽堂', NULL, '１３：３０〜１５：００（開場１３：００）石川県立能楽堂 講師：��橋 憲正(シテ方宝生流)、渡貫 多聞(ワキ方下掛宝生流) 定員：２０名 ●受講料：無料 お申込み方法 電話、メールにて受け付けています。 メールの場合は、以下の項目を明記のうえ、お申込みください。 �@氏名（ふりがな） �A電話番号 �B郵便番号・住所 �C白足袋の有無(お持ちでない方は足のサイズも記してください） ※複数人で参加を希望される場合は、全員の氏名を明記してください ※白足袋をお持ちでない方へは当日貸出も行います ※応募多数の場合は抽選 締切日以降にお電話やメール等でご連絡 募集締切：１０月４日（日） ■お申込み・お問合せ 石川県立能楽堂（月曜休館） 〒９２０−０９３５ 金沢市石引４丁目１８番３号 電話：０７６−２６４−２５９８ メール：noh@pref.ishikawa.lg.jp https://noh-theater.jp/news/20260809/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=10#51444', 0, 0);
