INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60597, '2026-11-01', '山口県', '鷺流狂言伝承140周年記念公演 クラウドファンディングによる支援者席あり', '野田神社能楽堂', '13:30', '13:30 野田神社能楽堂（雨天時：山口県教育会館） 狂言 抜殻 狂言 文荷 狂言 伯母ヶ酒 狂言 昆布売 狂言 鬼瓦 ●入場無料 正面の前側の席は支援者席になります。 クラウドファンディングで 10月1日から11月16日までご支援のお願いをしていくそうです。 https://yamaguchi-sagiryu.com/2026/09/29/post-617/ https://yamaguchi-sagiryu.com/2026/09/26/post-613/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51756', 0, 0);
