INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60601, '2026-11-01', '東京都', 'ふらっと能楽体験＠表参道', '銕仙会能楽研修所', '10:00', '午前10時〜12時（２時間） 会場 銕仙会能楽研修所 東京都港区南青山4-21-29 ワークショップの流れ 能や舞台の説明 面、装束、小道具の解説 仕舞実演 謡の体験 舞の体験（扇の持ち方、構え、摺足、型等） ●参加費 3,000円 当日受付にてお支払い 足袋、謡本、資料はこちらでご用意致します。 ※つき添い、見学の方も参加費を頂戴致します。 お申込み 下記サイトよりお申込み下さい。空き状況もご確認いただけます。 じゃらん 銕仙会能楽研修所 https://www.jalan.net/kankou/spt_guide000000186647/activity_plan/ アクティビティジャパン https://activityjapan.com/publish/feature/3032 お電話でも受け付けております。 また開催日以外でも条件次第で実施可能です。ご相談下さい。 銕仙会 電話 03-3401-2285（平日10-17時） http://www.tessen.org/active/triallesson', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51470', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60602, '2026-11-01', '東京都', '伝承ホール寺子屋 古典の日 公開講座「果てあるべからず 能 藝と伝承〜日本舞踊との比較の視点〜」', '渋谷区文化総合センター大和田6階伝承ホール', '17:00', '17:00開演（16:30開場） 会場 渋谷区文化総合センター大和田6階伝承ホール 出演 山階彌右衛門（能楽師シテ方観世流）、藤間豊彦（日本舞踊藤間流師範） 司会進行 鈴木英一（伝承ホール寺子屋プロデューサー） ●費用 渋谷区民3,500円/一般4,000円/当日券4,500円 ※全席指定（税込）、未就学児不可 申込 渋谷区民：9月20日〜（在住・在勤・在学を証明できるものを持参）/一般：9月28日〜文化総合センター大和田3階ホール事務室（10:00-19:00）にて直接販売。電話予約は、発売日に残席があった場合、翌日より受付。 ※一般販売はチケットぴあ（Pコード544-538） https://t.pia.jp （インターネット受付）をご利用ください。 ※当日券は、残席がある場合のみ開場時間より販売。 ※車椅子席はホール事務室にお■問い合わせください。 問：文化総合センター大和田3階ホール事務室 TEL：03-3464-3252（10:00-19:00）FAX:03-3464-3289 https://shibu-cul.jp/event/51391', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51687', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60603, '2026-11-01', '東京都', '友枝会', '国立能楽堂', '12:00', '時間：12時開場 13時開演 16時30分頃終演 場所：国立能楽堂 ★能「巻絹」 シテ：友枝雄人 ツレ：佐藤寛泰 ワキ：御厨誠吾 アイ：野村眞之介 笛：松田弘之 小鼓：観世新九郎 大鼓：大倉慶之助 太鼓：澤田晃良 地頭：大村定 ★狂言「舟ふな」 シテ：野村萬 アド：野村万蔵 ★能「阿漕」 シテ：友枝昭世 ワキ：宝生欣哉 ワキツレ：則久英志・渡部葵 アイ：野村拳之介 笛：一噌隆之 小鼓：成田達志 大鼓：國川純 太鼓：小寺真佐人 地頭：香川靖嗣 ●チケット S席：12,000円 A席：10,000円 B席：8,000円 C席：6,000円 D席：3,000円 ■予約開始 9月1日（火）11時〜 ■申込み ・友枝会チケット専用番号 03-5950-4543 ・ネット https://tomoeda.thebase.in/ https://tomoeda-kai.com/schedule-noh/7122/ https://kita-noh.com/schedule/19688/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#49457', 0, 0);
