INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60625, '2026-11-03', '大阪府', 'にしたなべ伝統芸能体験フェスタ', NULL, '09:00', '2026年11月3日(火・祝) 午前9時30分〜12時30分（3時間） 会場：山中能舞台（大阪市阿倍野区阪南町6丁目5-8） 子ども向けの伝統文化体験イベント 内容： 能 半能《高砂》 能面・摺り足・装束 囃子（笛・小鼓・大鼓・太鼓） 講談 くみ紐 出演： （能楽シテ方）山中雅志・井戸良祐・山田薫・藤井丈雄・塩谷惠 （能楽囃子方）赤井要佑・荒木建作・森山泰幸・上田慎也 （講談）旭堂南龍 （くみ紐）中井里佳 参加無料（要事前予約） 詳細： https://noh-and-kyogen.com/sorihashinoh/ お申込み: https://forms.gle/buFW5gAkM1SGdtk99', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51780', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60626, '2026-11-03', '大阪府', '日伊外交関係樹立160周年記念「レオナルド・ダ・ヴィンチを巡る能楽特別公演」200名招待 応募締切10月23日', '山本能楽堂', '12:30', '【公演名】日伊外交関係樹立160周年記念「レオナルド・ダ・ヴィンチを巡る能楽特別公演」 日時 2026年11月3日（火・祝） 開場12:30 開演13:00／終演17:00予定 【場 所】グラングリーン大阪ロートハートスクエアうめきた 【住 所】〒530-0011 大阪市北区大深町５（JR「大阪駅」うめきた地下口より直結） 公演プログラム 13：00 開会のご挨拶 13：10 クロストーク「2025年大阪・関西万博から世界へ（仮称）」 高科淳（2025年日本国際博覧会協会副事務総長） 中島さち子（大阪・関西万博テーマ事業プロデューサー） 山本 章弘（公益財団法人 山本能楽堂 代表理事） ほか 13：40 いのちの能「レオナルド・ダ・ヴィンチ」 老人/レオナルド・ダ・ヴィンチの霊 山本 章弘 モナ・リザの霊 山本 麗晃 画家を志す貧しい若者 原 大 笛：貞光智宣 小鼓：古田知英 大鼓：渡部 諭 太鼓：井上敬介 後見：大槻文蔵 梅若猶義 地謡：杉浦豊彦 吉井基晴 浦田保浩 井戸良祐 大槻裕一 クラゲバンド：中島さち子（ピアノ）、チェ・ジェチョル（韓国太鼓）、アブラインジャイインローズ（トーキングドラム）ほか 14：30 狂言「昆布売」 野村 太一郎 月崎 晴夫 15：00 いのちの能「時の輪」 時の神様 山本 章弘 くらげの精 善竹 隆平 茂山 忠三郎 善竹 顕久 茂山 良倫 茂山 緑里 笛：貞光智宣 小鼓：古田知英 大鼓：渡部 諭 太鼓：井上敬介 後見：梅若猶義 地謡：杉浦豊彦 吉井基晴 浦田保浩 井戸良祐 山本麗晃 クラゲバンド：中島さち子（ピアノ）、チェ・ジェチョル（韓国太鼓）、アブラインジャイインローズ（トーキングドラム）ほか ＊会場ご来場の皆様に、「2025年大阪・関西万博」参加国158か国の国旗をデザインしたクラゲ帽子をお渡し、最後は一緒に「クラゲ踊り」にご参加頂きます。 16：00 クラゲバンド コンサート クラゲバンド：中島さち子（ピアノ）、チェ・ジェチョル（韓国太鼓）、アブラインジャイインローズ（トーキングドラム）ほか 17：00 終演予定 ※プログラムの内容、時間は変更される場合があります。予めご了承ください。 200名様を無料ご招待 この公演に200名様を無料でご招待します。以下の応募フォームからお申込みください。 応募多数の場合は抽選のうえ、当選された方にのみ10月27日（火）午後5時までに、応募でご登録いただいたメールアドレスにメールでご連絡します。 ＜ご注意＞ ・おひとり4名様までのお申し込みが可能です ・出演者やプログラムは予告なく変更となる可能性があります。あらかじめご了承ください。 応募締め切り 2026年10月23日（金） 【問い合わせ】 ・公演について 山本能楽堂 電話：06-6943-9454（平日9:30-17:30） ・無料招待について 読売新聞大阪本社 メール：o-project.group@yomiuri.com 応募はこちらから https://www.yomiuri.co.jp/adv/idomu/noh2026/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51898', 0, 0);
