INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60632, '2026-11-03', '愛知県', '能「大江山」狂言「鬼継子」【やっとかめ文化祭 DOORS 2026 まちなか芸披露】', '名古屋能楽堂', '13:00', '13時開場 14時開演 名古屋能楽堂 ★狂言「鬼継子」 シテ/鬼 鹿島俊裕 アド/女 今枝郁雄 後見 佐藤友彦 ★能「大江山」 前シテ/酒呑童子 後シテ/鬼 内藤飛能 ワキ/源頼光 飯冨雅介 ワキツレ/独武者 橋本 宰 ワキツレ/立衆 岡 充 オモアイ/強力 井上松次郎 アドアイ/濯女 井上蒼大 笛 竹市 学 小鼓 後藤嘉津幸 大鼓 河村眞之介 太鼓 加藤洋輝 後見 衣斐 愛、坂口 侑 地謡 衣斐正宜、大友 順、和久荘太郎、東川尚史 竹内孝成、石森智幸、能勢 渉、中村成利 イヤホンガイド 日本語│米田真理（朝日大学教授） 英 語│奥田小夜子（能楽イヤホンガイド名古屋） ※演能の解説が聞ける受信機を無料でお貸しします。（日本語/英語） 狂言及び能解説│米田真理（朝日大学教授） ●一般4,000円、友の会会員・障がい者等3,000円、大学生（25歳）以下1,500円 （全席自由） チケットお申込み ※事業団友の会会員、障がい者等、大学生（25歳）以下の方は購入時に会員証、障がい者手帳等、学生証をご提示ください。 障がい者の方は、ご本人と付き添い1人まで割引価格でお求めいただけます。 ※割引との併用はできません。 ※未就学児の入場はご遠慮ください。 ※当日券は完売の場合を除き、12:30（開場時刻の30分前）から販売します。 チケットの取扱い まちなか芸披露 発売｜9/11（金）9:00 名古屋市文化振興事業団チケットガイド（平日9:00〜17:00／郵送可） TEL:052-249-9387 ※市内文化小劇場、アマノ芸術創造センター名古屋、青少年文化センター、名古屋能楽堂など、名古屋市文化振興事業団が管理する文化施設窓口（土日祝日も営業）でもお求めいただけます。 ※工事休館等がありますので、各施設のwebサイトでご確認ください。 teket https://teket.jp/g/fvwfnp81vy ※割引料金の場合は、事業団友の会会員証、障がい者手帳等、学生証を当日ご提示いただきます。 https://yattokame.jp/2026/hirou/6732.html 能楽写真家協会20周年記念展 能楽写真家から見る能狂言 会期10/1（木）〜11/18（水） 9:00〜17:00会場名古屋能楽堂 展示室 ●無料', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51648', 0, 0);
