INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60642, '2026-11-03', '神奈川県', '第26回よこはま「万作・萬斎の会」', '横浜能楽堂', '13:00', '13時 横浜能楽堂 解説 中村修一 小舞「芦刈」野村裕基 素囃子「早笛・舞働」 笛 栗林祐輔 小鼓 鳥山直也 大鼓 佃良太郎 太鼓 澤田晃良 狂言 馬口労 野村萬斎・飯田豪 狂言芸話 野村万作 狂言 連歌盗人 野村万作・高野和憲・深田博治 ●Ｓ席6,000円 Ａ席5,000円 Ｂ席4,000円 学生席3,000円 一般前売発売日 2026年9月30日（水）10:00 お求め先 チケットぴあ セブンイレブンでも取扱い有 カンフェティ TEL：050-3092-0051（電話受付時間 平日10：00〜17：00） ファンクラブyoiya2会員先行予約受付中！【受付期間 WEB会員：7/31（金）11:00〜8/16（日）23:59、郵便会員：2/13（木）消印有効】 現在ファンクラブ会員でない方で、会員先行予約への申込みをご希望の方は、申込期限までに新規会員登録の手続きを完了のうえお申込みください。 ※ 学生券のご予約は一般発売日11：00より万作の会 （TEL：03-5981-9778）にて承ります。 ※ 一般発売で売切の場合、キャンセル待ちを万作の会 （TEL：03-5981-9778）にて承ります。 ■お問い合わせ先 万作の会（TEL：03-5981-9778） https://mansaku.co.jp/information/performance/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51416', 0, 0);
