INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60654, '2026-11-06', '東京都', '国立能楽堂 定例公演', '国立能楽堂', '06:00', '午後６時30分開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 ◎能作者のまなざし −観世十郎元雅− 狂言 鬼の継子（おにのままこ） 野村 萬斎（和泉流）野村裕基 能 盛久（もりひさ） （観世流） 清水寛二 大日方寛 野口琢弘 則久英志 渡部葵 中村修一 笛 藤田貴寛 小鼓 後藤嘉津幸 大鼓 柿原弘和 地頭 西村高夫 ＊字幕あり（日本語・英語） 前売開始日 電話・インターネット予約＝10月10日（土）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/schedule/nou/2026/85030/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50039', 0, 0);
