INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60658, '2026-11-07', '京都府', '第１０６回 喜多流涌泉能', '大江能楽堂', '13:00', '13時 大江能楽堂 ★仕舞 熊坂 高林呻二 ★一曲独吟 安宅 高林白牛口二 ★能 三輪 高林昌司 福王知登 茂山茂 笛 貞光智宣 小鼓 成田奏 大鼓 山本寿弥 太鼓 中田一葉 附祝言 修了後 アフタートーク 16時半頃まで ●前売7000円 当日8000円 学生3000円 ■高吟会 ０７５−４６２−１４９０ お申し込みはこちらからでも https://www.eonet.ne.jp/~koginkai/ https://kita-noh.com/schedule/20008/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51831', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60659, '2026-11-07', '京都府', '能と中国茶を味わう会', NULL, '13:00', '京田辺市（参加者に場所はお知らせ） 京田辺市JR「同志社前駅」または近鉄「興戸駅」下車 参加費：3000円 1部 13:00〜15:30 2部 14:30〜17:00 『菊慈童』のお話とそれにちなんだ中国茶。美味しいお菓子付き。 講師 松井美樹 ●各部3000円 定員各部5名 お申込みは下記申込みフォームより https://docs.google.com/forms/d/1ixevXb9lTkTIzaPShgDsiuJhPb6yrluOP5BqkOC-LIo/viewform https://x.com/karashi0314/status/2097500012372795879', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51605', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60660, '2026-11-07', '兵庫県', '能楽の魅力と宍粟の伝統文化〜山崎八幡神社能舞台を中心に〜', NULL, '10:00', '11月7日（土） 山崎八幡神社 能舞台 10:00〜12:00 ・能舞台の魅力とは ・能面をかけて舞台を歩いてみよう ほか 山崎文化会館 13:00〜16:30 ・能の扇の魅力とは ・能装束を見て、触れてみよう ・お囃子の体験（宇原獅子舞と能楽） 11月8日（日） 山崎文化会館 10:00〜12:30 ・能の扇の魅力とは ・能装束を見て、触れてみよう ・お囃子の体験（宇原獅子舞と能楽） 山崎八幡神社 能舞台 16:30〜17:30 ・能舞台の魅力とは ・能面をかけて舞台を歩いてみよう ほか ※各体験は開催時間内で随時ご参加いただけます。 ※着付け体験・染め物体験・相撲体験も別途実施予定です。詳細はお問い合わせください。 ●参加無料 参加対象 未就学児・小学生以上の児童生徒・学生・保護者・一般の方 各体験は当日各先着50名、事前予約不要です。 白靴下または白足袋をご持参下さい なお、能楽教室・着付教室・染物教室・相撲教室については、別途お申込みを受け付けています。 お問い合わせはこちら https://www.matsunokai.com/event/2026-shiso-workshop/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51787', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60661, '2026-11-07', '兵庫県', '西宮能楽堂公演', NULL, '14:00', '14時 会場：西宮能楽堂 〒663-8184 西宮市鳴尾町3丁目6番20号 ○阪神鳴尾・武庫川女子大前駅下車、南へ徒歩約5分（地下通路を通ります。） ※駐車場・駐輪場はございません。公共交通機関をご利用下さい。 能「三輪」 女姿と三輪の神 演目と型の解説 指定席：4400円 自由席：3850円 ※当日各550円増 お申し込みは、 お電話：0798-48-5570（10時から17時） こちらからも受付 https://nishinomiya-noh.jp/schedule/2026%e5%b9%b4%e5%ba%a6-%e8%a5%bf%e5%ae%ae%e8%83%bd%e6%a5%bd%e5%a0%82%e5%85%ac%e6%bc%94-%e5%b9%b4%e9%96%93%e4%b8%80%e8%a6%a7', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#49916', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60662, '2026-11-07', '埼玉県', 'あげお能狂言鑑賞会', NULL, '13:00', '開場 13時30分 開演 14時00分 終了予定 16時00分 三井金属あげおコミュニティセンター（上尾市コミュニティセンター） ホール ★仕舞 鶴亀 梅若万佐志 ★仕舞 羽衣 梅若千音世 ★狂言 仏師 善竹大二郎 野島伸仁 ★能 楊貴妃 梅若泰志 善竹大二郎 笛 成田寛人 小鼓 幸信吾 大鼓 大倉正之助 地謡 伊藤嘉章 加藤眞悟 長谷川晴彦 定員 350席 ●参加費 Ａ席4,000円 Ｂ席3,500円 （全席指定） 対象 未就学児を除く全て ■問い合わせ 三井金属あげおコミュニティセンター Tel 048-775-0866 https://www.ageo-kousya.or.jp/event/detail.php?eid=00249', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51697', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60663, '2026-11-07', '山梨県', '一般社団法人「養老の森」主催 『秋の宴』 能、音、絵、食。', NULL, '12:00', '12:00〜15:30 受付 11:00〜11:40 ネイチャーランド オム 山梨県南都留郡道志村6018 茅葺古民家「白想亭」 ※11:40〜12:00は 舞台のある「雫カフェ」へお越しください。 【二つの舞台で日本文化を楽しむ】 12:00 雫カフェ「千手さくら舞台」 能面と装束による 能楽 ※参加者の雫カフェのご利用は ドリンクのみ受付時にオーダー承ります。 12:50 養老の森「紅葉がさね舞台」 能舞・琵琶・墨ライヴペイント 【秋の薬膳茶会で出演者と語らう】 14:15 茅葺古民家「白想亭」 おひとりおひとりの体調に合わせた薬膳茶と 『秋の宴』特製のお茶菓子とともに 白想亭を彩る12枚の墨絵襖も あわせてご覧いただけます ※雨天の場合は、舞台鑑賞を含むすべてのプログラムを 「白想亭」にて実施 【出演者】 観世流シテ方 能楽師 武田宗典 鶴田流 薩摩琵琶奏者 馬場一嘉 墨絵師 阿部朱華羅 パティシエール千々輪美紀 漢方養生指導士／自然観察指導員 伊勢美沙子 【参加費・定員】 15,000円（税込） 定員25名 ※小学生以下は観覧無料です。 薬膳茶・お茶菓子のご用意はございません。 必ず保護者同伴でお願いいたします。 【お申込み】 ・お名前 ・お電話 ・メールアドレス scaraceti33☆gmail.com ☆を＠に変えて送信 https://www.yoro-mori.com/11-7%E3%80%8C%E7%A7%8B%E3%81%AE%E5%AE%B4%E3%80%8D%E8%83%BD%E6%A5%BD%E3%81%A8%E7%90%B5%E7%90%B6%E3%81%A8%E5%A2%A8%E7%B5%B5-%E8%96%AC%E8%86%B3%E8%8C%B6%E3%81%A7%E6%87%87%E8%A6%AA%E4%BC%9A/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51668', 0, 0);
