INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60665, '2026-11-07', '愛知県', '能狂言がみたくなる講座 第2回 能と歌舞伎', '豊田市能楽堂', '14:00', '開演 14:00 開場 13:30 豊田市能楽堂 映画「国宝」を見て興味を持ったけど、能と歌舞伎ってどう違うの？ という、シンプルな疑問を解き明かす講座。 回は両者に共通する曲「道成寺」を素材に、声楽、器楽、舞踊、道具、ドラマの展開などの、さまざまな表現様式の違いを、映像を交えて解説 出 演 ゲスト／阿部さとみ（舞踊評論家・早稲田大学演劇博物館招聘研究員） 司会進行／金子直樹（能楽評論家） ●入場料 1,000円（全席自由） ※友の会会員は1割引、25歳以下は半額 問合せ 豊田市コンサートホール・能楽堂事務室 0565-35-8200 ※車いす席はお問い合わせください ※未就学児入場不可 発売日 友の会・一般共通（WEB・窓口・電話）／2026年7月18日（土）10:00〜 チケット発売場所 豊田市コンサートホール・能楽堂事務室（豊田参合館8階） TEL：0565-35-8200 https://www.t-cn.gr.jp/15451/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51300', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60666, '2026-11-07', '東京都', '2026年度東洋大学能楽鑑賞教室 学外の方は事前申込が必要 申し込み10月14日13時まで', '東洋大学白山キャンパス井上円了ホール', '14:30', '14時半 東洋大学白山キャンパス井上円了ホール 演目：能『羽衣 和合之舞』観世銕之丞（観世流） 狂言『附子』山本泰太郎（大蔵流） ●入場無料 本学学生と教職員は申込不要 学外の方は事前申込が必要です。 「 https://forms.gle/XtNAQsvUfvpgTtWD9 」 あるいはチラシのQRコードから 9月16日（水）〜10月14日（水）13時に必要事項を入力し、送信してください。 応募者多数の場合は抽選。 10月下旬に抽選結果をEメールにてお知らせします。 詳しくはこちら https://sites.google.com/toyo.jp/lit/news_f/%E8%83%BD%E6%A5%BD%E6%95%99%E5%AE%A4', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51793', 0, 0);
