INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60677, '2026-11-08', '兵庫県', '山崎能', NULL, '14:00', '14時から16時 山崎八幡神社能舞台（宍粟市山崎町） 雨天 山崎文化会館ホール 能 羽衣 杉浦豊彦 ●無料 事前申し込み不要 チラシの方に能の予定が載ってます https://www.matsunokai.com/event/2026-shiso-workshop/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51769', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60678, '2026-11-08', '兵庫県', '能楽の魅力と宍粟の伝統文化〜山崎八幡神社能舞台を中心に〜', NULL, '10:00', '11月8日（日） 山崎文化会館 10:00〜12:30 ・能の扇の魅力とは ・能装束を見て、触れてみよう ・お囃子の体験（宇原獅子舞と能楽） 山崎八幡神社 能舞台 16:30〜17:30 ・能舞台の魅力とは ・能面をかけて舞台を歩いてみよう ほか ※各体験は開催時間内で随時ご参加いただけます。 ※着付け体験・染め物体験・相撲体験も別途実施予定です。詳細はお問い合わせください。 ●参加無料 参加対象 未就学児・小学生以上の児童生徒・学生・保護者・一般の方 各体験は当日各先着50名、事前予約不要です。 白靴下または白足袋をご持参下さい なお、能楽教室・着付教室・染物教室・相撲教室については、別途お申込みを受け付けています。 お問い合わせはこちら https://www.matsunokai.com/event/2026-shiso-workshop/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51788', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60679, '2026-11-08', '埼玉県', '川口リリア リオープン記念公演 狂言師 野村万作・萬斎の世界', NULL, '15:00', '15:00 川口総合文化センターリリア フカガワみらいホール（メインホール） ★解説：野村萬斎 ★狂言『萩大名』 大名：野村万作 (人間国宝) 太郎冠者：内藤 連 亭主：石田幸雄 ★狂言『棒縛』 太郎冠者：野村裕基 主：高野和憲 次郎冠者：中村修一 ★狂言『茸(くさびら)』 山伏：野村萬斎 何某：深田博治 茸：金澤桂舟 中村修一 飯田 豪 梶原睦希 梶原充喜 梶原元煕 石田淡朗 鬼茸：岡 聡史 ●全席指定 S席4,000円 A席3,000円 前売 7/25(土)〜 【リリアメンバーズ取扱有】 全席指定 S席3,600円 A席3,000円 リリアメンバーズ先行受付 7/24(金)〜 リリア・チケットセンター 048-254-9900 (10:00〜17:00 ※月曜定休、祝日の場合は翌火曜休業) リリア・ネットチケット http://lilia.or.jp/ticketinet/ 備考 ※料金は全て税込価格 ※未就学児の入場不可 ※『フカガワみらいホール(メインホール)』での開催 ※出演者・曲目等は変更となる場合がございます 公演中止の場合を除き、チケットの払戻・変更等はいたしません ※2階･3階席への移動は階段となります （ホワイエにエレベーターが新設され、1階席フロアから2階席フロアまでご利用いただけます） ※車椅子席については、リリア・チケットセンターのみでのお取扱いとなります https://www.lilia.or.jp/event/3644', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51286', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60680, '2026-11-08', '大阪府', '教えて能楽師！', NULL, '15:00', '14：00〜15：00 【場所】藤田美術館 土間（エントランス） 講師 上田宜照さん（観世流シテ方能楽師） ※予約不要、参加無料。展示をご覧になる場合は、入館料1,000円いただきます（19歳以下無料） 2026年の「教えて能楽師！」開催日程 3/22(日)、5/17(日)、7/26(日)、9/27(日)、11/8(日) いずれも14〜15時 https://fujita-museum.or.jp/ https://fujita-museum.or.jp/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50521', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60681, '2026-11-08', '大阪府', '教えて能楽師！〜観能編〜', NULL, '15:30', '14-15時半 藤田美術館 料金：7,000円 ※先着順で80名のみの販売となります。 ご予約はコチラ https://my-site-106093-108187.square.site/#most-popular https://fujita-museum.or.jp/noh_gasyouen_fujitamuseum/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51775', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60682, '2026-11-08', '大阪府', '阿倍野区能楽講座「能への誘(いざな)い」天下人・秀吉は、能で何を伝えたかったのか？―「豊公能」に映る思い', '阿倍野図書館 多目的室', '14:00', '日時：11月8日（日） 14時〜16時 定員：50名（事前申込制・先着順） 講師：朝原 広基（あさはら ひろき）さん 能楽と郷土を知る会代表、大阪大学大学院 人文学研究科 博士後期課程（演劇学・能楽）在籍 豊臣秀吉は、能をこよなく愛した天下人でした。自らの生涯や業績を題材とする「豊公能」を作らせ、それを自ら舞ったことは、秀吉ならではの特徴です。なぜ秀吉は、自らの人生を能にしたのでしょうか。 「豊公能」を読み解きながら、秀吉の人物像に迫ります。 場所 阿倍野図書館 多目的室（大阪市阿倍野区阿倍野筋4-19-118） 申込 阿倍野図書館へ来館または電話（06-6656-1009）による申込。 10月6日（火曜日）10時から受付開始（事前申込制・先着順。開館時間内のみ受付） 参加無料 https://www.city.osaka.lg.jp/abeno/page/0000686205.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51718', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60683, '2026-11-08', '広島県', '秋能祭', NULL, '11:00', '11時から12時 備後護国神社能舞台 連吟「福山」 男性組 仕舞「羽衣」 大島衣恵 独調「枕慈童」 大島紀恵 仕舞「猩々」 大島文恵 ●無料 https://noh-oshima.com/schedule_j/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51483', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60684, '2026-11-08', '愛知県', '青陽会研究能', '名古屋能楽堂', '02:30', '開演１２時半 会場 名古屋能楽堂 能 賀茂 吉沢旭、伊藤裕貴、橋本宰、椙元正樹、高安受壽、井上松次郎、山村友子、福井聡介、河村裕一郎、加藤洋輝 狂言 栗焼 今枝郁雄、鹿島俊裕 仕舞 野宮 星野路子 仕舞 松虫 松山幸親 仕舞 山姥 久田三津子 能 半蔀 山脇由美子、飯冨雅介、井上蒼大、竹市学、船戸昭弘、河村眞之介 チケット 一枚4000円、学生2000円、回数券(2公演分)7000円 https://kyogen.co.jp/performance/%e4%bb%a4%e5%92%8c%ef%bc%98%e5%b9%b4%e5%ba%a6%e3%80%80%e5%85%ac%e6%bc%94%e4%ba%88%e5%ae%9a/?post_id=4338', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#49512', 0, 0);
