INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60687, '2026-11-08', '東京都', '六区 能', NULL, '19:00', '１９：００（開場時間 １８：００） Date: November 8th, 2026 Time: 19:00 p.m.~, 場所：浅草ビューホテルアネックス六区 １階レストラン「ブロードウェイ六区」 Place: Asakusa view hotel Annex Rokku, 1F Restaurant "Broadway Rokku" 出演 坂真太郎 ●一般入場料：５,０００円（宿泊者無料） Fee: Free for guests of View Hotel Annex / JPY 5,000 / 1person with One Drink and food menu available while watching Noh Performance. ※ご入場の際はワンドリンク制となります。 ※フードのオーダーも可能 【１１月及び１２月の内容】 １１月、１２月の演目は、「巻絹（まきぎぬ）」「猩々（しょうじょう）」「葛城（かずらき）」。 https://www.viewhotels.co.jp/asakusa-annex/event/9/ https://www.shinnohsho.net/post/%E3%80%90%E3%82%B9%E3%82%BF%E3%83%BC%E3%83%88%EF%BC%81%E3%80%91%E6%B5%85%E8%8D%89%E3%83%93%E3%83%A5%E3%83%BC%E3%83%9B%E3%83%86%E3%83%AB%E3%82%A2%E3%83%8D%E3%83%83%E3%82%AF%E3%82%B9%E5%85%AD%E5%8C%BA%E3%81%AB%E3%81%A6%E3%80%81%E8%83%BD%E6%A5%BD%E3%82%A4%E3%83%99%E3%83%B3%E3%83%88%E9%96%8B%E5%82%AC%EF%BC%81', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51835', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60688, '2026-11-08', '東京都', '大江宏に関する石山修武氏公開インタビュー・第2回大江フェス', '梅若能楽学院会館', '13:30', '13:30-18:00 梅若能楽学院会館（東京都中野区東中野2-6-14） 第1部 石山修武氏公開インタビュー（法政大学デザイン工学部建築学科主催・梅若能楽堂研究会共催） 13:30-15:00 話し手：石山修武（早稲田大学理工学部 名誉教授） 聞き手：石井翔大（日本文理大学工学部建築学科 准教授） 司会：藤本貴子（法政大学デザイン工学部建築学科 専任講師） 大江フェス（法政大学藤本研究室・梅若能楽堂研究会主催） 第2部 仕舞「巻絹」「鶴」 15:15-16:00 能楽師：松山隆之・梅若景英 第3部 レクチャー、研究・活動報告 16:30-18:00 １．大江新太郎の遺産 扇湖山荘の再生事業 発表者：坂野正崇（建築家） ２．大江宏設計九十八叟院 耐震改修終了の報告 発表者：藤井明、松本郁（小平市平田中彫刻美術館） ３．普連土学園体育館・高3校舎記録ワークショップの報告 発表者：普連土学園生徒有志＋法政大学藤本研 全体コメンテーター：小堀哲夫（法政大学デザイン工学部建築学科 教授）、藤原徹平（横浜国立大学大学院Y-GSA 准教授） ポスター発表（ロビーにて同時開催） ・測るワークショップ報告 ・普連学園体育館・高3校舎記録ワークショップ報告（普連土学園生徒有志＋藤本研） ●参加無料、出入自由（仕舞実演中は出入不可） https://umewaka.org/schedule/1263', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51890', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60689, '2026-11-08', '東京都', '能トモプロジェクトＶｏｌ．９＜観世九皐会定例会（観世流）「俊寛」「鉄輪」を観に行こう！＞', '矢来能楽堂', '02:00', '矢来能楽堂（東京都新宿区矢来町６０） ＜第一部＞１２時３０分開演／＜第二部＞１５時３０分開演 募集人数：各部・先着１０名（合計２０名） 座席：指定席・中正面席（座敷席最後列・イスあり） 演目 ＜第一部＞能「俊寛」長山耕三、解説（観世喜正）、仕舞 ＜第二部＞能「鉄輪」新井麻衣子、解説（佐久間二郎）、狂言「鈍太郎」三宅近成 ●料金＆チケット内容 （１）【各部】書籍なしチケット：５，０００円 （２）【各部】書籍セットチケット「Ａ ＧＵＩＤＥ ＴＯ ＮＯ」：６，２００円 （３）【第一部のみ】書籍セットチケット「対訳でたのしむ俊寛」：５，６００円 （４）【第二部のみ】書籍セットチケット「対訳でたのしむ鉄輪」：５，６００円 （５）【第一部のみ】書籍セットチケット「Ａ ＧＵＩＤＥ ＴＯ ＮＯ」＆「袖珍本 俊寛」：７，０００円 （６）【第二部のみ】書籍セットチケット「Ａ ＧＵＩＤＥ ＴＯ ＮＯ」＆「袖珍本 鉄輪」：７，０００円 すべてのチケットに《能サポ字幕サービス（日本語・英語対応、専用タブレット配布）》が付きます。 書籍セットチケットは、書籍代が通常より《約２０％》お得になります。 詳細・お申込みはこちら https://hinokishoten.hp.peraichi.com/nohtomo/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51723', 0, 0);
