INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60703, '2026-11-09', '岐阜県', '狂言 大藏流誠翔会 高山公演', NULL, '18:15', '開場18:15／開演19:00 会場 高山市民文化会館 大ホール お話し 大藏基誠 狂言 盆山 茂山忠三郎 山本善之 狂言 文相撲 大藏基誠 田中惇之 大藏康誠 狂言ワークショップと質問コーナー 狂言解体新書 ●一般3,000円／メセナメイト会員2,500円／ジュニア(18才以下)500円 ※未就学児入場不可 チケット発売日 9/26(土) メセナメイト先行発売10:00〜／一般発売13:00〜 チケット取り扱い 高山市民文化会館、チケットぴあ(Pコード544-393) 『令和８ 年度 文化庁 劇場・音楽堂等における子供舞台芸術鑑賞体験支援事業』 本公演は、文化庁の支援により、18才以下の方は無料、同伴者の方も半額でご覧いただけます。 但し、子どもの人数により以下の様に半額割引となる同伴者の人数が変わります。 子ども1〜2名…同伴者1名が半額 子ども3〜4名…同伴者2名が半額 子ども5〜6名…同伴者3名が半額 上記以上の人数の同伴者でお申込みいただいた場合 超過する分は通常料金となりますが、並びで席をご用意。 お申し込みは、9/8(月)から9/23(水)まで受け付け https://www.takayama-bunka.org/20261109kyogen/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51435', 0, 0);
