INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60714, '2026-11-11', '東京都', '2026学習院桜友会特別フォーラム', NULL, '06:00', '１．日 時 令和８年１１月１１日（水曜日） 午後6時〜7時30分（開場午後5時） ２．場 所 学習院創立百周年記念会館 正堂 ３．演 題 AI時代に人としてどう生きるか ４．講演者 狂言師 野村 万蔵 氏 メディアアーティスト・研究者 落合 陽一 氏 ５．対象者 学習院卒業生・在学生以外の方もご参加いただけます（定員に達し次第締切） ６．主 催 一般社団法人学習院桜友会・講座委員会 ●無料 【お申し込みについて】 ・当日はご参加者各人の入場券が必要です。 ・WEB申込フォームよりお申し込みください。（1つの申込書につき、1名様分のお申し込みを承ります） ・WEBからのお申し込みが難しい場合は、FAX用申込フォームをご利用ください。 ・お申し込み完了後、申込完了をお知らせする自動返信メールが発信されますが、自動返信メールが迷惑フォルダに届く場合もございますので、ご留意ください。 ・入場者の決定は、入場券の発送をもって代えさせていただきます。 WEB申込フォーム https://www.gakushuin-ouyukai.jp/form/~forum2026/ FAX申込フォーム 【入場券の受取方法について】 ＜メールでの受取をご希望の場合＞ 当日受付時にご提示いただく入場券を、11月４日（水）以降メールにてお送りします。 なお、迷惑メールのブロック設定をされている場合は、「forum@gakushuin-ouyukai.jp」からのメールが届くよう、事前の設定をお願い致します。 ＜ハガキでの受取をご希望の場合＞ 当日受付時にご提示いただく入場券を、10月以降ハガキにてお送りします。 【お席について】 混雑時には、ご利用いただくお席を、当日会場にて係りの者より指定させていただく場合がございます。 【駐車場について】 駐車場のご用意はございませんので、公共交通機関をご利用ください。 【問い合わせ先】 桜友会事務局 特別フォーラム担当 Email：forum@gakushuin-ouyukai.jp Tel：03-3988-3288 FAX : 03-3988-3853 https://www.gakushuin-ouyukai.jp/topics/5389/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51876', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60715, '2026-11-11', '東京都', 'かなえの会 能楽NOTEvol.3', '国立能楽堂', '18:30', '18時半から20時15分 国立能楽堂二階研修能舞台 ［各楽器の手組とその関係性］ 小鼓方大倉流 清水和音 大鼓方高安流 柿原孝則 太鼓方観世流 澤田晃良 ゲスト 宝生流シテ方 辰巳和麿 ●参加費4000円 https://x.com/sWNQ2ufp3zKDMqm https://www.facebook.com/kanae.noh.kai/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51704', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60716, '2026-11-11', '東京都', '国立能楽堂 定例公演', '国立能楽堂', '01:00', '午後１時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 狂言 茫々頭（ぼうぼうがしら） 茂山千三郎（大蔵流）大藏彌右衛門 能 井筒（いづつ） 物着（ものぎ） 金井 雄資（宝生流）福王知登 笛 松田弘之 小鼓 幸正佳 大鼓 國川純 地頭 小倉健太郎 ＊字幕あり（日本語・英語） (2026/01/07) 前売開始日 電話・インターネット予約＝10月10日（土）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50040', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60717, '2026-11-11', '高知県', '土佐の「こじゃんと」能楽プロジェクト', NULL, '17:00', '17時45分開場 高知県立美術館 18時15分 中庭石舞台（屋外） オープニングパフォーマンス 能「猩々」短縮版 観世喜正 大日方寛 笛 槻宅聡 小鼓 曽和鼓堂 大鼓 亀井広忠 太鼓 桜井均 地謡 林本大 河村浩太郎 上田顕崇 会場：能楽堂（屋内） トークイベント 島崎和歌子 観世喜正 狂言「寝音曲」��澤祐介 三宅右矩 能「大江山 替之型」観世 喜正 林 彩八子 林 小梅 大日方 寛 御厨 誠吾 宝生 朝哉 小林 克都 梅村 昌功 三宅 近成 前田 晃一 笛 森田 勝瀧 小鼓 曽和 鼓堂 大鼓 亀井 広忠 太鼓 桜井 均 地謡 上田 拓司 吉井 基晴 大西 礼久 林 喜右衛門 長山 桂三 林本 大 山中 雅志 藤井 丈雄 ●全席指定席 A席 7,000円 B席 5,000円 学生券（小中高） 2,000円 販売期間 前売りチケット 2026年9月18日（金）午前10時より発売開始 ※販売終了はそれぞれ下記の通り。 ・11月公演：11月10日（火） ※上記を過ぎてからのチケットのご購入については当日券になります。 ※販売期間にかかわらず、チケットが売り切れ次第、販売を終了 チケット購入 チケットぴあ (WEB / セブンイレブン Pコード 545-037) https://t.pia.jp/pia/ticketInformation.do?eventCd=2633493&rlsCd=001 カンフェティ (WEB / 電話予約 050-3092-0051) https://www.confetti-web.com/events/17862 会場窓口・店頭等での購入について 高知県立美術館ミュージアムショップ 088-866-7653 高知県立県民文化ホール 088-824-5321 https://www.nohgaku.or.jp/kojanto2026', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51683', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60718, '2026-11-11', '高知県', '高知県立美術館 能楽公演2026 土佐の「こじゃんと」能楽プロジェクト 体験ワークショップ', NULL, '16:00', '16:00開始（15:45開場 / 17:00終了予定） 高知県立美術館 能楽堂 建築・構造美と伝統芸能の融合を多角的に楽しむ特別体験。 ・舞台機構の実演解説： 巨大な能舞台が出現する仕組みを公開 ・オン・ステージ体験： 舞台上で能楽師から学ぶ、摺り足・足拍子 ・能面の世界を体感： 実際に面をつけて、能楽師が見ている世界を体感 ●一般：2,000円 ／ 学生券（小中高）：1,000円 ※本公演セット割引：本公演チケット提示で500円キャッシュバック 販売期間 2026年9月18日（金）午前10時より発売開始 ※売り切れ次第、販売終了 チケット購入 チケットぴあ (WEB / セブンイレブン Pコード 545-037) https://t.pia.jp/pia/ticketInformation.do?eventCd=2633493&rlsCd=001 カンフェティ (WEB / 電話予約 050-3092-0051) https://www.confetti-web.com/events/17863 https://www.nohgaku.or.jp/kojanto2026', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51684', 0, 0);
