INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60721, '2026-11-12', '愛知県', 'やっとかめ文化祭 旅するなごや学 【名匠狂言会連携企画】「THE 狂言談義 パート�U」', '名古屋能楽堂', '16:00', '16:00〜17:00 会 場 名古屋能楽堂 会議室（名古屋市中区三の丸1-1-1） 地下鉄鶴舞線「浅間町」駅1番出口から東へ徒歩10分 地下鉄名城線「名古屋城」駅7番出口から西へ徒歩12分 市バス「名古屋城正門前」下車すぐ（栄13系統、栄27系統、西巡回系統） なごや観光ルートバスメーグル「名古屋城」下車すぐ 定 員 80名 講 師 野村萬斎（東京和泉流）、茂山千五郎（京都大蔵流）、井上松次郎（名古屋和泉流） 聞き手 林和利（伝承文化研究センター所長） ●参加費 講座単独券：2,500円 名匠狂言会S席＋講座セット券：13,000円 名匠狂言会S席＋講座セット券については、「名匠狂言会」公式サイトよりご参照ください。 名匠狂言会公式サイト https://static.chunichi.co.jp/chunichi/pages/event/kyogen/ ※なお人気企画につき、売り切れの場合はご容赦ください。 https://yattokame.jp/2026/nagoyagaku/7895.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51650', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60722, '2026-11-12', '愛知県', '名匠狂言会', '名古屋能楽堂', '18:00', '18時開場 18時半開演 名古屋能楽堂 狂言「二人袴」茂山千五郎 茂山竜正 茂山あきら 茂山茂 狂言「法師ヶ母」野村万作 野村萬斎 笛 竹市学 小鼓 後藤嘉津幸 大鼓 河村眞之介 狂言「簸屑」佐藤友彦 野村又三郎 井上松次郎 9月10日（木）10：00から発売 ●入場料 S席 11,000円 A席 9,000円 B席 8,000円 （全席指定・税込み） 入場券取扱い場所 ・中日新聞コンサートデスク TEL. 052-678-5323 ・Boo-Wooチケット ・ローソンチケット（Lコード：43505） ・チケットぴあ（Pコード：544-548） ・イープラス ※中日新聞販売店でも取り扱い お問い合わせ 中日新聞コンサートデスクTEL.052-678-5323(平日11:00〜17:00) 名匠狂言会×やっとかめ文化祭DOORS連携企画 旅するなごや学「THE 狂言談義パート�U」 名匠狂言会に出演する東京和泉流、京都大蔵流、名古屋和泉流から気鋭の狂言師が、狂言の魅力を余すところなく語り合います。 11月12日（木）16時開始（約60分） 名古屋能楽堂会議室 出演 野村萬斎、茂山千五郎、井上松次郎 聞き手＝伝承文化研究センター・林和利所長 チケット 名匠狂言会S席＋やっとかめ講座セット券＝13,000円（Boo-Wooチケット・ローソンチケットで販売） ※セット券は名匠狂言会S席のみ。A席B席の設定はありません。 ※講座の単独券（2,500円）は、teketにて9月11日から販売開始 https://static.chunichi.co.jp/chunichi/pages/event/kyogen/index.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51522', 0, 0);
