INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60736, '2026-11-14', '愛知県', '能楽堂で見る日本の伝統芸能シリーズ52「京舞と能〜人間国宝 井上八千代の至芸〜」', '豊田市能楽堂', '13:30', '13時半開場 14時開演 豊田市能楽堂 地歌「菊の露」 井上八千代 対談 井上八千代・片山九郎右衛門 休憩（20分） 舞囃子「海士 玉之段」観世淳夫 地歌「珠取海女」井上安寿子 舞囃子「邯鄲」片山九郎右衛門 地歌「邯鄲」井上八千代 出 演 井上八千代 片山九郎右衛門 井上安寿子 観世淳夫 ほか ●全席指定／5,000円（25歳以下2,500円） 発売日 友の会先行発売（WEB・窓口・電話）／2026年6月27日（土）10:00〜 一般発売（WEB・窓口・電話）／2026年7月4日（土）10:00〜 チケット発売場所 豊田市コンサートホール・能楽堂事務室（豊田参合館８階） TEL:0565-35-8200 ＜プレイガイド＞ チケットぴあ https://t.pia.jp/ （Pコード：543-017） ■問合せ 豊田市コンサートホール・能楽堂事務室 TEL：0565-35-8200 ※車いす席はお問い合わせください ※未就学児入場不可 https://www.t-cn.gr.jp/15207/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51117', 0, 0);
