INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60738, '2026-11-14', '東京都', '国立能楽堂 普及公演', '国立能楽堂', '01:00', '午後１時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 解説・能楽あんない 班女という名前 ―能の曲名から読み取れること― 宮本圭造（法政大学能楽研究所所長） 狂言 栗焼（くりやき） 茂山あきら（大蔵流）茂山千之丞 能 班女（はんじょ） （金春流） ��橋忍 野口能弘 野口琢弘 渡部葵 茂山茂 笛 成田寛人 小鼓 飯田清一 大鼓 石井景之 地頭 辻井八郎 ＊字幕あり（日本語・英語） (2026/01/07) 前売開始日 電話・インターネット予約＝10月10日（土）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50041', 0, 0);
