INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60759, '2026-11-15', '栃木県', '第10回おやま市民大学 能楽ことはじめ〜初めての方の能楽入門〜／能面・能装束展', '小山市立生涯学習センター えるる OYAMA ホール・ギャラリー', '14:00', '小山市立生涯学習センター えるる OYAMA ホール・ギャラリー （〒323−0023 小山市中央町3−7−1 ロブレ6階） 第1回：令和8（2026）年11月15日（日曜日）14時&#12316;16時 （13時30分開場） 第2回：令和8（2026）年11月22日（日曜日）14時&#12316;16時 （13時30分開場） 講師 金春流能楽師、山中一馬氏 【能面・能装束展】 令和8（2026）年11月15日（日曜日）13時30分&#12316;11月22日（日曜日）16時 展示時間：期間中9時&#12316;17時 ※初日・最終日を除く 対象者・申込み条件 対象：中学生以上 定員：70人 （定員を超えた場合は、市内在住・在勤・在学の方を優先し、抽選を実施します） 参加料 ●無料 申込みについて 申込み期間：10月1日（木曜日）&#12316;10月23日（金曜日） 申込み方法：専用フォーム（インターネット）もしくは電話 ※定員に満たない場合は、申込み期間終了後も先着順で受付を行います。 ※講座の様子を撮影し、広報活動に使用することがあります。ご了承ください。 ■生涯学習文化課 生涯学習係 〒323-0023 栃木県小山市中央町3丁目7番1号 ロブレビル6階 電話番号：0285-22-9665 FAX番号：0285-22-9116 https://www.city.oyama.tochigi.jp/kurashi/sports-shogaigakushu/shogaigakushu/page011256.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51423', 0, 0);
