INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60766, '2026-11-17', '京都府', '国際交流の夕べ 能と狂言の会 2026', '京都観世会館', '18:00', '18時 京都観世会館 邦楽（尺八・箏・三絃） 石 橋 三好 芫山 狂言 素袍落 茂山千五郎 能 天 鼓 片山九郎右衛門 ●全席自由 一 般 3,500円 学 生 2,000円 ■お問合わせ先：国際交流基金 京都支部 TEL 075-762-1136 受付時間：月〜金 10時−17時 京都観世会館ではWEB販売・対面販売のみ 電話予約不可 https://www.kyoto-kanze.jp/show_info/20261117show_meeting/ https://www.jpf.go.jp/j/world/kyoto/2026/11-01.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51678', 0, 0);
