INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60768, '2026-11-17', '北海道', '市民参加型ワークショップ「能楽大連吟札幌」', '札幌市教育文化会館', '16:00', '開催日 2026年11月17日（火） 〜 2027年3月22日（月） 開催場所 札幌市教育文化会館 研修室 401 ワークショップ開催日 ＜オリエンテーション＞ 2026年11月17日（火）18：30開始 ＜お稽古日程＞ 2026年12月3日（木）、15日（火） 2027年１月19日（火）、２月16日（火）、３月２日（火） 各回とも18：30開始 ＜リハーサル＞ 2027年３月21日（日） 16:00開始 会場：教育文化会館 大ホール 発表公演 2027年３月22日（月・祝） 会場：教育文化会館 大ホール ●参加費（税込） 一般 12,000円（教文ホールメイト会員は500円引） U-30 9,500円 親子ペア 17,500円（小中学生までのお子さんと親子２人の料金） ※参加費にはオリエンテーション、稽古、発表公演出演料を含みます ※お稽古および本番には能楽の謡扇（長さ30cm程度)が必要となります。くわしくはお問い合わせください。 お申込みは専用フォームから 【能楽大連吟札幌 お申込みフォーム】 https://www.kyobun.org/wsform.php 応募対象：小学３年生から 定員：60名（先着順） 募集開始：7月22日（水） 講師 観世流シテ方能楽師 松野浩行、斉藤信輔、樹下千慧 ■お問い合わせ 札幌市教育文化会館 事業課 TEL 011-271-5822（休館日除く9時〜17時） https://www.kyobun.org/event_schedule.html?id=12043', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51811', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60769, '2026-11-17', '愛知県', '能講座「トヨトミ イズ ダンシング〜謡・仕舞編」', NULL, NULL, '秀吉公が生まれた場所 「太閤山常泉寺」で、 前回開催した能講座 「トヨトミ イズ ダンシング」 今回は、さらに、 能を身近に感じてもらおうと、 実際の舞台稽古場を会場にして開催します。 「例 （演目）羽衣」 不時着してしまった天女と 漁師が出会い、 惹かれ合う物語。 人間と天女という 越えられない世界の違い、 一緒にいたいのに、 一緒には生きられない。 だからこそ、 相手を信じ、 自由にする。 そして最後は、 自分の幸せよりも相手の幸せを選びます。 最後に残ったのは 「あなたに出会えてよかった。」 という想い。 『羽衣』という能が、 ６００年以上もの間、 人の心を動かし続けているその理由を、 喜びや悲しみを謡い、 そして舞う・・ 実際の舞台の上で 天女の気持ちを体感してください。 全３回、下記の演目よりお届けします。 「鶴亀」 愛でたいを全力で祝う、 究極の祝祭エンタメ。 「羽衣」 天女と漁師の出会い、 羽衣をめぐる奇跡の一日。 「高砂」 ずっと一緒に、 夫婦の絆を描く、 永遠のラブストーリー。 ※「仕舞」を体験される方は 「白足袋」をご持参ください。 場所は新栄駅徒歩３分の場所になります。 初心者大歓迎、講座はどの月からでも参加できますので、 是非、お気軽にお越しください。 ＝＝＝＝＝＝＝＝＝＝＝＝ ＜愛知で能楽を普及する会＞では、 名古屋市内で能を楽しく知ってもらう「能イベント」 神社や稽古場等で気軽に学べる「能楽講座」を開催しています。 天下の三英傑の嗜み、そしてかの太閤豊臣秀吉も晩年は心酔した能の世界。 難しいと敬遠されがちな能をマンガを通じて読み解したり、 能楽師さんとのコミュニケーションを通じて、その奥深さを感じてください。 イベントでは喫茶など名古屋文化に舌鼓を打ちながら歴史を学んだり、 謡を聴いたりして「静」の時を、 講座ではじっくりと仕舞や謡を体験しながら「動」の時を、 是非、能を通じて五感を整えましょう。 詳細は下記、 愛知で能楽を普及する会 https://www.nagoya-nishio-noh.com/ 〜名古屋 西尾 能楽講座〜 公式ホームページは「名古屋西尾能」で検索。', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51451', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60770, '2026-11-17', '石川県', 'MANSAI FANTASY BOX 野村萬斎&オーケストラ・アンサンブル金沢 「真夏の夜の夢」', '石川県立音楽堂', '19:00', '19時 石川県立音楽堂 真夏の夜の夢 出演 野村萬斎・野村裕基・深田博治・高野和憲・月崎晴夫・中村修一・内藤連・飯田豪・石田淡朗・嘉和道彦・佐辺良和 ほか ●全席指定 S8,500円A7,000円B5,000円 未就学児入場不可 ・一般発売日：2026年8月17日 10:00 ・OEK定期会員、邦友会会員は各10%割引 ・公演予定時間: 約120分 https://t.pia.jp/pia/ticketInformation.do?eventCd=2620977&rlsCd=001&lotRlsCd= https://teket.jp/14595/70776?uid=HP ■お問合わせ先 石川県立音楽堂チケットボックス TEL： 076-232-8632 https://www.oek.jp/event/mansai-fantasy-box', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51693', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60771, '2026-11-18', '東京都', '藝大定期 邦楽 第92回 〜邦楽科開設90周年記念〜', NULL, '17:00', '17:00開演（16:00開場） 日本橋公会堂 ★雅楽 盤渉調「 竹林楽 」 ★尺八 琴古流・都山流 吹き合わせ 「 鹿の遠音・鶴の巣籠 」 ★能楽宝生流 仕舞 「 岩 船 」 シテ 宝生和英 地謡 水上優 木谷哲也 山本万祐子 渡邊真之助 ★能楽 観世流 舞囃子「 葛 城 大和舞 」 シテ 観世清和 笛 藤田貴寛 小鼓 飯田清一 大鼓 安福光雄 太鼓 林雄一郎 地謡 観世三郎太 藤波重彦 清水義也 関根祥丸 久田勘吉郎 ★清元・日本舞踊 「 薫る寿 」 香取 仙之助 作詞 清元 梅吉 作曲 ★箏曲生田流 「 夢 殿 」 宮城 道雄 作曲 ★現代邦楽囃子 「 月にむかって打て 」 ★箏曲山田流 「 須磨の嵐 」 山登 萬和 作曲 ★長唄・邦楽囃子 「 舌出し三番叟 」 二世 杵屋 正治郎 作曲 ●入場料 4,000円（全席指定） チケット取り扱い ◆チケット：9月16日（水）販売開始 ヴォートル・チケットセンター TEL：03-5355-1280／平日 10:00〜18:00 チケットぴあ《Pコード336 &#8211; 987 》 イープラス（e+） ■お問い合わせ 東京藝術大学演奏藝術センター TEL:050-5525-2300 ※就学前のお子様の同伴・入場はできませんので、ご了承ください。 https://www.geidai.ac.jp/container/sogakudo/161356.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51671', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60772, '2026-11-19', '京都府', 'ゼロから始める お能講座', NULL, '13:30', '13時半から15時 株式会社北村 京都市中京区室町通三条上ル役行者町368 ３階 京都市営地下鉄東西線「二条城前駅」徒歩5分 『修羅能 清経』 修羅能とは？清経の能を紹介。 講師：金剛流シテ方 宇��徳成 ●2,000円 お申し込みはこちらから https://forms.gle/17FfCMJR5UKzxyQG8 https://x.com/udakanorishige/status/2061625084176138303/photo/3', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50962', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60773, '2026-11-19', '京都府', '第13回 文化サロン 「能楽 京都のまちに深く根差した伝統芸能」', '金剛能楽堂', '09:25', '京都迎賓館 午前の部 9:25集合 10:00開始 12:40終了（予定） 午後の部 13:25集合 14:00開始 16:40終了（予定） 講師 能楽金剛流 二十六世宗家・人間国宝 金剛 永謹 氏 及び 若宗家・金剛 龍謹 氏 主な内容(予定) ・能の魅力や歴史についての説明や実演を交えた解説 ・金剛能楽堂所蔵の貴重な能面・能装束等の展示 ・通常非公開の「水明の間」を含む館内ガイドツアー 定員 午前の部 80名 午後の部 80名 ●参観料金 一般：5,000円 大学生：3,500円 中高生：1,500円 ※1 小学生以下はご参観いただけません。 ※2 中高生又は大学生割引を適用される場合は、参観当日に必ず受付で生徒手帳又は学生証をご提示ください。 ※3 有効期間内の身体障害者手帳、療育手帳、精神障害者保健福祉手帳、戦傷病者手帳、被爆者健康手帳又はMIRAIROをお持ちのかたと介護者（1名まで）は料金が免除となります。 申込受付 下記のリンクからお申込みください。 「第13回 文化サロン」のお申込みはこちらから（先着順） https://form.geihinkan.go.jp/entry/p01?lang=ja&place=kyoto 定員に達した時点で申込受付を終了 https://www.geihinkan.go.jp/kyoto/2026autumn/bunkasalon13/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51803', 0, 0);
