INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60777, '2026-11-20', '東京都', '国立能楽堂 企画公演', '国立能楽堂', '06:00', '午後６時30分開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 ◎琵琶と能楽 筑前琵琶 大楠公（だいなんこう） 奥村 旭翠 狂言 伯養（はくよう） ��澤 祐介（和泉流）前田晃一 三宅右矩 能 楠露（くすのつゆ） （観世流） 山階彌右衛門 観世三郎太 武田祥照 武田智継 笛 野口亮 小鼓 観世新九郎 大鼓： 本哲也 地頭 岡久広 ＊字幕あり（日本語・英語） 前売開始日 電話・インターネット予約＝10月10日（土）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝7,300円 脇正面＝5,700円（学生4,000円） 中正面＝4,600円（学生3,200円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50042', 0, 0);
