INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60780, '2026-11-21', '京都府', '令和8年度 醍醐寺でひらく笑いの扉〜はじめての狂言体験〜 （第2回）京都市内に在住又は通勤・通学の小学生以上の方（小学生は保護者同伴）', NULL, '09:00', '総本山 醍醐寺 三宝院 （〒601-1325 京都市伏見区醍醐東大路町22） （第2回）令和8年11月21日（土曜日）午前9時30分から正午まで（受付開始：午前9時） 伝統芸能・狂言の鑑賞（演目は、醍醐寺に縁のある「口真似（くちまね）」を予定） 狂言のミニ講座、体験 醍醐寺の施設見学 対象 （第2回）京都市内に在住又は通勤・通学の小学生以上の方（小学生は保護者同伴） 定員 各50名（申込多数の場合は抽選） ●参加料 無料 「京都いつでもコール」へ、電話・FAX・申込用フォームいずれかの方法で、申込期間中にお申込みください。申込多数の場合、抽選後に当落の通知を電話又はメールにてお知らせします。 申込期間 （第2回）令和8年9月25日（金曜日）から令和8年10月14日（金曜日） 申込項目 1.代表者氏名（ふりがな）、2.郵便番号、3.住所（通勤・通学要件に該当の場合はその旨）、4.年齢、5.電話番号、6.メールアドレス、7.同伴者人数、8.同伴者氏名（ふりがな）、9.同伴者年齢 京都いつでもコール 年中無休（受付時間：午前8時から午後9時まで） ・電話：075-661-3755 ・FAX：075-661-5855（おかけ間違いにご注意ください。） ・申込フォーム外部サイトへリンクします（申込受付中のイベントから選択のうえ、申込フォームから申し込み。） ■問合せ 伏見区役所醍醐支所地域力推進室まちづくり担当 電話：075-571-6135（直通） https://www.city.kyoto.lg.jp/fushimi/page/0000353987.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50950', 0, 0);
