INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60789, '2026-11-21', '広島県', '第３７回ひろしま平和能楽祭 お申込み期限 令和８年１０月１６日（金）必着', NULL, '13:00', '13時 ＪＭＳアステールプラザ・中ホール能舞台 （広島市中区民文化センター） 御挨拶・解説 藤波重孝 能 「千手 郢曲之舞」観世清和 杉浦豊彦 福王茂十郎 笛 杉市太郎 小鼓 横山幸彦 大鼓 山本哲也 地頭 上田貴弘 狂言「左近三郎」茂山七五三 茂山宗彦 仕舞「屋島」藤波重孝 仕舞「西行桜」観世恭秀 仕舞「網之段」井上嘉介 仕舞「天鼓」上田拓司 能 「葵上 梓之出 空之祈」観世三郎太 田口亮二 福王知登 茂山逸平 笛 杉市太郎 小鼓 横山幸彦 大鼓 山本哲也 太鼓 中田弘美 地頭 山階彌右衛門 ４００名さま（２００組）を無料ご招待 座席 座席（１・２階）は、全席指定 お申込み 入場券ご希望の方は往復はがきに「入場券希望」と明記の上 住所・氏名・電話番号を記入して事務局までお申込みください。 はがき一枚につき、１組２名さまの申込みとさせていただきます。 申込み多数の場合は、抽選とし抽選結果は１１月上旬までにはがきでお知らせいたします。 お申込み先 〒７３０−８７０７ 広島市中区富士見町３−１５ 広島信用金庫内 公益財団法人ひろしん文化財団 宛 お申込み期限 令和８年１０月１６日（金）必着 お問い合わせ先 ＴＥＬ０８２−２４５−０５１２ （広島信用金庫本店内事務局） https://www.hiroshin.co.jp/info/2026/260918_2.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#50488', 0, 0);
