INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60828, '2026-11-23', '神奈川県', '落合陽一×日本フィルプロジェクトVol.10 《離見する音楽会》', '横浜能楽堂', '14:00', '横浜能楽堂 14:00（13:30 開場） 17:00（16:30 開場 ） 出演者 演出：落合陽一 シテ方観世流：梅若紀彰（能楽監修、出演） シテ方観世流：梅若景英 囃子方：笛/栗林祐輔 小鼓/飯冨孔明 大鼓/大倉慶乃助 太鼓/小寺真佐人 地謡：松山隆之、川口晃平、山崎友正、鷲尾雄紀 日本フィルハーモニー交響楽団メンバー ヴァイオリン：田野倉雅秋［ソロ・コンサートマスター］ ヴァイオリン：末廣紗弓 ヴィオラ：小中澤基道 チェロ：門脇大樹［ソロ・チェロ］ フルート：真鍋恵子［首席奏者］ 曲目 ドビュッシー（富田勲）：月の光＜４CHシンセサイザー音源＞ 能楽「井筒」より J.S.バッハ：無伴奏ヴァイオリンソナタ第2番《グラーヴェ》 ドホナーニ：弦楽三重奏のためのセレナードより第3楽章 能楽「嵐山」より 武満徹：エア 能楽「山姥」より ペルト：スンマ（弦楽四重奏＋舞） ラヴェル：弦楽四重奏曲より 他 ●全席指定 SS：10,000円 ※日本フィル・READYFORのみ取扱 S：8,000円 A：6,000円 Ys（25歳以下、A席より選択）/車いす・同伴（1名まで）：2,500円 ※日本フィルのみ取扱 ダイバーシティ料金（障害者手帳保持者）：SS：5,000円、S：4,000円 A：3,000円 ※日本フィルのみ取扱 14時公演 https://japanphil.or.jp/concert/20261123-14/ 17時公演 https://japanphil.or.jp/concert/20261123-17/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51865', 0, 0);
