INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60834, '2026-11-25', '東京都', '銕仙会定期公演〈12月〉事前講座「松虫」「春日龍神」', '銕仙会能楽研修所', '18:00', '時間：18時より（20時頃終了予定） 会場：銕仙会能楽研修所 ２階能舞台 ※本公演の会場（観世能楽堂）とは場所が異なりますのでご注意下さい 講師：原瑠璃彦（静岡大学准教授）、鵜澤光、観世淳夫 ●受講料 資料代500円 ※当日会場にてお支払い下さい ※本公演のチケットをお持ちの方は無料 ■お申込み 銕仙会 TEL 03-3401-2285 ※平日10〜17時 ※要事前申込み http://www.tessen.org/schedule/regular/2026reg12', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51828', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60835, '2026-11-25', '神奈川県', '野村萬斎 狂言の夕べ', NULL, '18:00', '18時30分 開演 （18時開場）ハーモニーホール座間 大ホール 解説：高野 和憲 【 演 目 】 「萩大名はぎだいみょう」 大名：野村 萬斎 太郎冠者：中村 修一 亭主：石田 幸雄 後見：深田 博治 「首引くびひき」 親鬼：野村 裕基 鎮西八郎為朝：飯田 豪 姫鬼：内藤 連 眷属：月崎 晴夫、高野 和憲、深田 博治、岡 聡史 後見：中村 修一 ●全席指定 5,500円 チケット購入 ハーモニーホール座間 事務所 8/22(土)まで スカイアリーナ座間内 8/23(日)から 8/30(日)まで 移転のため休業 8/31(月)から ハーモニーホール座間内 ハーモニーホール座間 046-255-1100 一般プレイガイド チケットぴあ t.pia.jp ローソンチケット l-tike.com e＋（イープラス） eplus.jp その他プレイガイド Ro-Onチケット 047-365-9960 ヨコハマよみうりプレイガイド 050-3387-1517 未就学児入場不可 7月30日(木) 発売 初日一人4枚まで ■お問合せ Ro-Onチケット 047-365-9960 （平日10時から18時、土曜10時から14時、日祝休み） ハーモニーホール座間 046-255-1100 注意事項 ※なお、お電話でのお問い合わせ・チケット予約の際は、電話番号をお確かめの上、お間違いのないようにお願いします。 ※チケット購入の為、発売日前から並ぶことはご遠慮ください。 ※営利目的のチケットの転売は禁止します。 ※チケット発売初日は指定のない場合、午前9時より会館窓口で販売いたします。電話予約はその後、午前10時より取り扱いますが、窓口で売り切れた場合、購入できませんのでご容赦ください。 ※ご購入後の変更やキャンセル、紛失による再発行は出来ません。 https://harmony.zamashi.jp/events/detail/2026_11_25_m.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51297', 0, 0);
