INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60842, '2026-11-27', '東京都', '国立能楽堂ガイドツアー', '国立能楽堂', '07:00', '開催日時 令和8年 11月27日（金）午後7時 12月22日（火）午後2時／午後7時 令和9年 1月26日（火）午後2時／午後7時 3月4日（木）午後2時／午後7時 ※ツアー所要時間 約2時間 ※開場時間は、各回開始1時間前 見学場所 国立能楽堂 能舞台・楽屋・客席・ロビー・展示室（1/26、3/4） ※ミニ鑑賞および能楽体験付き ※英語通訳あり ※靴を脱ぎ、靴下に履き替えていただく場所がございます（靴下は貸出します）。 ※写真撮影OK（一部撮影不可エリアあり） ご案内 令和8年 11月27日（金）午後7時 シテ方金春流 山井綱雄/井上貴覚/本田布由樹/中村昌弘 囃子 栗林祐輔/清水和音/柿原孝則/金春惣右衛門 12月22日（火）午後2時／午後7時 未定 令和9年 1月26日（火）午後2時／午後7時 未定 3月4日（木）午後2時／午後7時 未定 ●参加料金 4,000円 ※各回40名様限定 ※施設見学のみ（客席・ロビー・展示室（1/26、3/4））は、予約不要・無料です。ミニ鑑賞・体験はできません。 ［見学時間：午後2時30分〜午後4時（11/27除く）、午後7時30分〜午後9時］ 予約開始 令和8年 11月27日（金）の回：10月10日（土）午前10時 12月22日（火）の回：11月10日（火）午前10時 令和9年 1月26日（火）の回：令和8年12月10日（木）午前10時 3月4日（木）の回：令和9年2月10日（水）午前10時 ※売り切れの場合がございますので、予めご了承ください。 【電話】国立劇場チケットセンター 0570（07）9900 https://www.ntj.jac.go.jp/topics/nou/2026/guidedtour2026/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51733', 0, 0);
