INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60854, '2026-11-28', '東京都', '東京都庭園美術館「庭園能」2日目', '東京都庭園美術館芝庭', '11:00', '時間：第1部：開場11:00 / 開演11:30 / 終演13:00 第2部：開場14:30 / 開演15:00 / 終演16:00 場所：東京都庭園美術館 芝庭 （雨天時：喜多能楽堂） 第1部 ★解説 高林昌司 ★仕舞「蝉丸」友枝昭世 ★能「清経」 シテ：香川靖嗣 ツレ：佐藤陽 ワキ：大日方寛 笛：一噌隆之 小鼓：成田達志 大鼓：大倉慶乃助 第2部 ★解説 佐藤陽 ★仕舞「経政 ｷﾘ」友枝昭世 ★能「二人乱」 シテ：友枝雄人 シテ：佐藤寛泰 ワキ：大日方寛 笛：杉信太朗 小鼓：成田達志 大鼓：大倉慶乃助 太鼓：澤田晃良 ●各公演・全席指定・税込 S席（正面席）：7,000円 A席（脇正面席・中正面席）：5,000円 ※未就学児のご入場はご遠慮いただいております。また、こども料金の設定もございません。 ※車いすで公演をご覧いただく場合は、事前に東京都庭園美術館 庭園能担当（TEL 03-3443-0201）までご相談ください。 ■チケット前売開始 9月1日（火）10:00〜 ■チケット申し込み カンフェティ http://confetti-web.com/@/teien-noh2026 TEL 050-3092-0051 ※平日10:00〜17:00 ※オペレーター対応 ■問い合わせ 喜多能楽堂 TEL 03-3491-8813（平日10:00〜18:00／火〜金） https://kita-noh.com/schedule/19816/ https://www.teien-art-museum.ne.jp/event/teien-noh_1127/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51428', 0, 0);
