INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60860, '2026-11-28', '神奈川県', '井伊掃部頭直弼ゆかりの出演者、土地で開催 第40回 横浜かもんやま能', '横浜能楽堂', NULL, '開場 13：00 開演 14：00 横浜能楽堂 能楽師による実技と解説 安藤 貴康 狂言「鎧」（大蔵流） シテ（主人） 茂山七五三 アド（太郎冠者） 茂山千五郎 アド（すっぱ） 茂山 宗彦 後見 茂山 逸平 能「養老 水波之伝」（観世流） シテ（樵翁・山神） 観世銕之丞 前ツレ（樵夫） 青木 健一 後ツレ（楊柳観音） 観世 淳夫 ワキ（勅使） 宝生 常三 ワキツレ（従者） 野口 能弘 ワキツレ（従者） 小林 克都 笛 藤田 貴寛 小鼓 住駒 充彦 大鼓 柿原 弘和 太鼓 小寺真佐人 地頭 西村 高夫 ●S席 5,000円 A席 4,000円 B席 3,500円（全席指定） 一般発売 令和８年８月２２日（土）正午より 横浜能楽堂LINE友だち会員先行 令和８年８月１８日（火）正午〜８月２０日（木） ※WEBのみで受付 ※先行発売枚数には限りがあります WEBサイトからのお申込み 横浜能楽堂オンラインチケット お問い合わせ 横浜能楽堂 TEL：045-263-3055 https://yokohama-nohgakudou.org/schedule/3175160.html?page=3', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51183', 0, 0);
