INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60862, '2026-11-28', '鹿児島県', '宝山プレゼンツ 鹿児島県文化センター開館６０周年記念 野村萬斎・裕基「狂言への誘い」', '佐渡', '10:00', '開場１２:１５ 開演１３:００ 会場 宝山ホール（鹿児島市山下町５番３号） 狂言のお話 野村萬斎 狂言「佐渡狐」（さどぎつね） 佐渡の百姓：深田 博治、越後の百姓：内藤 連、奏者：石田 幸雄 狂言「二人袴」（ふたりばかま） 親：野村 萬斎、聟：野村 裕基、舅：高野 和憲、太郎冠者：月崎 晴夫 ●全席指定 Ｓ席８,５００円 Ａ席６,５００円 Ａ席（Ｕ−２５）５,０００円 ※当日各５００円増 ※Ａ席（U-25）は鑑賞時に25歳以下の方が対象です。 入場時に年齢の確認できるものの提示を求めることがあります。 ※車いす席をご希望の方は宝山ホールにお問い合わせください。 ※未就学児の入場・同伴はお断りします。 【子ども無料招待席（アップルシート）について】 県内の小・中・高校生３０名様をご招待します。 応募方法は後述のとおりです。 【団体割引について】 10枚以上1割引、20枚以上2割引でご提供いたします（同時購入に限らせて頂きます）。 詳細は、後述の「団体割引申込書」をご覧のうえ、様式をダウンロードいただき、メール又はファックスでお申し込みください。 ・団体割引申込書 様式ダウンロード（Word・PDF） お問合せは宝山ホールまで（099-223-4221 受付時間8：30〜19：00 休館：月曜 ※但し月曜が祝日の場合は、直後の平日） かごしまミューズ・クラブ会員web先行予約 8月11日（火・祝）10：00〜 かごしまミューズ・クラブ会員先行電話予約 8月11日（火・祝）13：00〜 プレイガイド 先行 ぴあ・ローソン・イープラス・CNプレイガイドについては、次の期間で先行予約も可能です。 8月16日(日)12：00〜8月20日(木)18：00 ※プレイガイド先行期間後は、一般発売期間にお買い求めいただけます。 鹿児島音協会員先行 8月18日（火）10:00〜 一般web発売 8月22日（土）10：00〜 一般発売 8月22日（土）10：00〜 ※宝山ホールでの電話予約は13：00〜 入場券販売所 ※チケットの前売りは公演日の2日前までとなります。 〇当財団web予約・購入についてはこちら 〇チケットぴあ Pコード：541-870 https://t.pia.jp/ 〇ローソンチケット Ｌコード：81341 https://l-tike.com/ 〇イープラス https://eplus.jp/ 〇CNプレイガイドTEL:0570-08-9999 https://www.cnplayguide.com/ 宝山ホール、山形屋、十字屋クロス（S席のみの取り扱い）、鹿児島音協、県庁生協、谷山サザンホール、みやまコンセール ◎子ども無料招待席（アップルシート） 県内の小学生〜高校生３０名（抽選）をご招待 &#9332; 応募資格 鹿児島県内の小学生〜高校生。指定期日までに宝山ホールにてチケットの引き換えが可能な方（郵送対応可。送料４６０円） &#9333; 応募方法 応募フォームからご応募ください。 &#9334; 募集期間 ７月４日（土）１０時〜８月４日（火） &#9335; 当落通知 メールにて当落結果とチケットの引き換え方法を通知します。 【アップルシート協賛企業様】 （敬称略 50音順） ・株式会社沖宣工社 ・鹿児島信用金庫 ・南国殖産株式会社 ・株式会社フォーエバー ・株式会社南日本銀行 https://www.houzanhall.com/news/info-promote/16237/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51358', 0, 0);
