INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60876, '2026-11-29', '香川県', '「能と雅楽」', NULL, '02:00', '【日程】2026年11月29日（日） 【開演】午後2時（開場：午後1時30分） 【場所】ユープラザうたづハーモニーホール 【番組】 第1部 雅楽三昧 「中村さんち」 中村仁美、 中村香奈子、 中村華子 第2部 能 経政 シテ 伶以野 陽子 ワキ 安田 登 笛 赤井 要佑 小鼓 成田 奏 大鼓 森山 泰幸 後見 奥川 恒治 地謡 山中 &#36819;晶、山中 雅志、藤井 丈雄、山田 薫 【料金】前売り5,000円（当日券5,500円） ※全席指定/未就学児の入場不可 【プレイガイド】 ・ユープラザうたづ Tel.0877-49-8020 ・アイレックス Tel.0877-86-6800 ・マリンウェーブ Tel.0875-56-5111 ・サクラートたどつ Tel.0877-33-3330 ・ハイスタッフホール Tel.0875-23-3939 ・朝日段ボールホール国分寺（高松国分寺ホール）Tel.087-875-0162 ・源内音楽ホール Tel.087-894-1000 ・三木町文化交流プラザ Tel.087-898-9222 ・香川県庁消費生活協同組合 Tel.087-832-3822 ・ローソンチケット【Lコード：62252】 ・WEBチケット販売 ※WEBチケットは9月1日（火）9時30分〜から販売開始。 ・駐車台数には限りがありますので公共交通機関などをご利用ください。周辺施設及び月極駐車場への無断駐車は禁止です。また周辺道路は駐車禁止です。 【主催】一般財団法人宇多津町振興財団 【後援】宇多津町、宇多津町教育委員会、丸亀市教育委員会 【助成】一般財団法人地域創造 https://uplaza-utazu.jp/uplaza_post/5172/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51505', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60877, '2026-11-30', '東京都', '第15回 喜多流職分 中村邦生の謡曲講座『龍田』', '市川房枝記念婦選会館', '10:30', '●場所 市川房枝記念婦選会館 東京都渋谷区代々木2-21-11 ・JR新宿駅南口・代々木駅西口徒歩10分 ・大江戸線A1出口徒歩5分 ●日時（全６回） 10月 5日（月）10:30〜12:00 10月19日（月）10:30~12:00 11月 16日（月）10:30〜12:00 11月30日（月）15:30〜17:00 12月 7日（月）10:30~12:00 12月21日（月）15:00~16:30 ●講座内容 ・謡の実演 ・謡曲の美しい日本語を声に出して楽しむ ・能の話、能楽師の仕事、舞台裏話など ●講師 能楽師シテ方喜多流職分 中村邦生 ●受講料 一括受講 ￥12,000（全6回） 単回受講 ￥3,000（1回） ※別途テキスト代2,100円 喜多流謡本『龍田』 ※喜多流謡本をお持ちの方はお持ちください。 単回受講の方はご相談ください。 ※講座内容の録音配信での受講もご相談に応じます。 ■お問合せ 中村邦生の会事務所 TEL 03-5310-5690', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=11#51760', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60878, '2026-12-01', '宮城県', '実演解説', NULL, '18:30', '東京都 【能楽囃子体験入門 わーくしょっぷ 第二回 大小の世界と竹生島の実演解説】 18時半開始 大和花道舞台 東京都新宿区百人町２−１７−１０ アクセス JR山手線・新大久保駅改札を出て左。3つ目の信号を右折。 JR総武線・大久保駅北口改札を出て右。2つ目の信号を左折。 講師 清水和音 能楽師小鼓方大倉流 講師 柿原孝則 能楽師大鼓方高安流 ●参加費 4000円 詳しくはこちら 申し込みなどもこちらを https://kakiharatakanori.amebaownd.com/posts/54766087?categoryIds=5878178 https://www.jp-bags.com', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51901', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60879, '2026-12-01', '東京都', '第六十七回 響の会', '銕仙会能楽研修所', '18:00', '18時開場 18時半開演 銕仙会能楽研修所 狂言 木六駄（きろくだ） 太郎冠者 山本泰太郎 主人 山本凜太郎 茶屋 山本 則重 伯父 山本 則秀 能 鉢木 （はちのき） 佐野源左衛門常世 清水 寛二 常世ノ妻 北浪 貴裕 旅僧 西明寺時頼 大日方 寛 二階堂某 渡部 葵 早打 山本凜太郎 二階堂供者 山本東次郎 笛 松田 弘之 小鼓 鵜澤洋太郎 大鼓 柿原 弘和 地頭 西村 高夫 ●全席指定 座席は桟敷席、最後列にベンチ席有り 正面席 7,000円 脇正面席 5,000円 U25席 （25歳以下） 3,000円 お申込み チケット発売日 ８月17日（月） インターネット 午前10時より 電話受付 初日午後１時より GETTIIS https://www.gettiis.jp/event/detail/100424/E35515 銕仙会 電話 03-3401-2285（平日午前10時〜午後5時） 事前講座「現代から、鉢木と木六駄を読む」 会 場 銕仙会能楽研修所 日 時 2026年11月17日（火）午後6時30分より 講 師 小田幸子 参加費 500円（チケットをお持ちの方は無料） お申込み 銕仙会TEL03-3401-2285（平日午前10時&#12316;午後5時）※要事前申込み http://www.tessen.org/schedule/kikaku/261201_hibikinokai https://www.hibikinokai.com', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51395', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60880, '2026-12-01', '神奈川県', '横浜能楽堂 体験講座 はじめの一歩（大鼓を打つ）', '横浜能楽堂', '19:00', '19:00〜20:00 横浜能楽堂 第二舞台 講師 佃良太郎（大鼓方高安流） ●参加料 2,000円 申込｜7月11日（土）14時〜 ※先着順 ※定員20名 ※当日は靴を脱ぎますので、靴下をご着用の上、ご参加ください。 ※正座をしますので、膝の出ない服装でご参加ください。 ※いただいた個人情報は当ワークショップ以外の目的では使用いたしません。 ※お支払いいただきました参加費は、事業中止の場合を除き返金いたしません。 ※内容・出演者に変更がある場合がございます。あらかじめご了承ください https://yokohama-nohgakudou.org/schedule/3283099.html?page=3', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51182', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60881, '2026-12-02', '東京都', '国立能楽堂 定例公演', '国立能楽堂', '01:00', '午後１時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 狂言 縄綯（なわない） 高野 和憲（和泉流） 能 遊行柳（ゆぎょうやなぎ） 青柳之舞・朽木留（あおやぎのまい・くちきどめ） 観世 清和（観世流） ＊字幕あり（日本語・英語） (2026/01/07) 前売開始日 電話・インターネット予約＝11月10日（火）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou.htm', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#50044', 0, 0);
