INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60883, '2026-12-02', '東京都', '近藤乾之助先生を語る会分科会 第7回 能の不思議を楽しむ会', '国立能楽堂', '17:00', '時間：17時30分開場 18時開始 20時頃終了予定 場所：国立能楽堂 大講義室 上映予定演目： 能「望月」 シテ：近藤乾之助（60歳） ワキ：森茂好 アイ：野村万之丞（当時） 笛：藤田大五郎 小鼓：鵜澤壽 大鼓：柿原崇志 太鼓：金春惣右衛門 （1988（昭和63）年10月11日 近藤乾三の会） ゲスト： 村上湛（明星大学教授） 金井雄資（能楽師 宝生流シテ方） 参加費（全席自由）： 一般 2,500円（当日 3,000円） 学生 1,500円（当日 2,000円）※当日受付にて学生証をご呈示ください 申込方法： 事前の郵便振替でのご入金が必要となります 〈11月26日締切〉 ※メールでのお申し込みの必要はございません ・窓口またはATM ゆうちょ銀行 口座記号番号：00130=0=451625 ・ｲﾝﾀｰﾈｯﾄﾊﾞﾝｷﾝｸﾞ ゆうちょ銀行 当座預金 〇一九（ｾﾞﾛｲﾁｷｭｳ）支店 店番：019 口座番号：0451625 加入者名：近藤乾之助先生を語る会 ※11月27日以降のお申し込みは、当日受付にてお支払いください 問い合わせ先： noh.fushigi@gmail.com http://kondo-kennosuke.com/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51912', 0, 0);
