INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60920, '2026-12-08', '東京都', '第41回・久習會公演', '国立能楽堂', '06:00', '午後6時00分開演 国立能楽堂（千駄ヶ谷駅・北参道駅） 素謡「攝待 （せったい）」（観世流） シテと地頭:荒木 亮 子方:大日方 樹 ワキ:福王和幸 義経と副地頭:山中雅志 兼房と地謡:齋藤和則 鷲尾と地謡:橋岡伸明 マリコウジ新作狂言「道行かず（みちゆかず）」 百姓甲：茂山逸平 百姓乙：茂山 茂 男：島田洋海 能「菊慈童（きくじどう）」（観世流） シテ：雲龍櫻子 ワキ：福王和幸 笛：藤田貴寛 小鼓・森澤勇司 大鼓・大倉正之助 後見：梅若雅一・山中ガ晶 地頭：橋岡伸明、地謡・山中雅志、小早川泰輝、小早川康充、土田英貴、齋藤和則 附 祝言 ●全席指定席 Ａ（正面席）＝10000円 Ｂ（脇正面席）＝6000円 Ｃ（中正面席）＝4000円 Ｄ（学生＆外国人）席はＢと同じ＝2000円 チケットはこちらから https://kyushukai.cafe.coocan.jp/41.html カンフェティにも少しあるようです。 https://www.confetti-web.com/events/17637', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51578', 0, 0);
