INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60922, '2026-12-09', '埼玉県', 'みよし能', NULL, '18:30', '開場18:30 ／ 開演 19:00 コピスみよし 終演予定時間 21:00（予定） 見どころ解説 小島英明 狂言『清水』野村萬斎 内藤連 能『土蜘蛛』小島英明 桑田貴志 新井麻衣子 石井寛人 宝生常三 梅村昌功 則久英志 飯田豪 笛 藤田貴寛 小鼓 飯冨孔明 大鼓 佃良太郎 太鼓 澤田晃良 地謡 駒瀬直也 永島充 奥川恒成 金子仁智翔 ●全席指定 一 般 3,800円 三芳町民 3,000円 25歳以下 2,000円 第23回竹間沢車人形公演（12/6公演）とのお得な伝統芸能セット券 みよし能 一般3,800 + 車人形 一般1,500円＝5,300円 → 4,500円 ※未就学児はご入場いただけません。 ※障がい者手帳割引、団体割引（10名以上〜）があります。詳細はお問い合わせください。 ※予約開始日 9/12はご予約のみ（窓口でのチケットのお受取りは9/13から） ■お問い合わせ コピスみよし（三芳町文化会館） TEL：049-259-3211 開演前、終演後に鶴瀬駅西口より、シャトルバスの運行を予定。 https://yarai-nohgakudo.com/archives/13933 https://t.pia.jp/pia/ticketInformation.do?eventCd=2636214&rlsCd=001 https://www.miyoshi-culture.jp/event/33486/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51662', 0, 0);
