INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60925, '2026-12-09', '高知県', '土佐の「こじゃんと」能楽プロジェクト 能楽公演２０２６', NULL, '18:15', '18:15開演（17:45開場／21:00終演予定）高知県立美術館 オープニングパフォーマンス 会場：中庭石舞台（屋外） 能「猩々」 ※短縮版にて シテ 猩々 観世 喜正 ワキ 高風 福王 知登 笛 松田 弘之 小鼓 久田 舜一郎 大鼓 山本 哲也 太鼓 前川 光長 地謡 弘田 裕一 鷹尾 章弘 角当 直隆 能楽堂（屋内） 解説 神戸学院大学准教授の中村健史 一管「下り端」笛方・森田勝瀧 狂言「濯ぎ川」 シテ 男 茂山 逸平 アド 女房 島田 洋海 アド 姑 鈴木 実 能「綾鼓」 シテ 庭掃きの老人／前同人の霊 粟谷 明生 ツレ 女御 狩野 祐一 ワキ 臣下 福王 知登 アイ 臣下の従者 茂山 逸平 笛 松田 弘之 小鼓 久田 舜一郎 大鼓 山本 哲也 太鼓 前川 光長 後見 中村 邦生 粟谷 浩之 地謡 長島 茂 狩野 了一 金子 敬一郎 内田 成信 佐々木 多門 大島 輝久 佐藤 陽 谷 友矩 ・オープニングの能「猩々」(約15分）は、屋外の中庭石舞台で上演します。 ・屋外は【立ち見】です。(一部座席あり) 段差などにお気を付けください。 ・鑑賞後は屋内の能楽堂へ移動し、指定席へご着席ください。 ・雨天時は「猩々」を含む全演目を能楽堂（全席指定）にて上演します。 ●全席指定席 A席 7,000円 B席 5,000円 学生券（小中高） 2,000円 販売期間 前売りチケット 2026年9月18日（金）午前10時より発売開始 ※販売終了はそれぞれ下記の通り。 ・12月公演：12月8日（火） ※上記を過ぎてからのチケットのご購入については当日券になります。 ※販売期間にかかわらず、チケットが売り切れ次第、販売を終了させていただきますので予めご了承ください。 チケット購入 チケットぴあ (WEB / セブンイレブン Pコード 545-037) https://t.pia.jp/pia/ticketInformation.do?eventCd=2633493&rlsCd=001 カンフェティ (WEB / 電話予約 050-3092-0051) https://www.confetti-web.com/events/17862 会場窓口・店頭等での購入について 高知県立美術館ミュージアムショップ 088-866-7653 高知県立県民文化ホール 088-824-5321 https://www.nohgaku.or.jp/kojanto2026', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51686', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60926, '2026-12-09', '高知県', '高知県立美術館 能楽公演2026 土佐の「こじゃんと」能楽プロジェクト 体験ワークショップ', NULL, '16:00', '16:00開始（15:45開場 / 17:00終了予定） 高知県立美術館 能楽堂 建築・構造美と伝統芸能の融合を多角的に楽しむ特別体験。 ・舞台機構の実演解説： 巨大な能舞台が出現する仕組みを公開 ・オン・ステージ体験： 舞台上で能楽師から学ぶ、摺り足・足拍子 ・能面の世界を体感： 実際に面をつけて、能楽師が見ている世界を体感 ●一般：2,000円 ／ 学生券（小中高）：1,000円 ※本公演セット割引：本公演チケット提示で500円キャッシュバック 販売期間 2026年9月18日（金）午前10時より発売開始 ※売り切れ次第、販売終了 チケット購入 チケットぴあ (WEB / セブンイレブン Pコード 545-037) https://t.pia.jp/pia/ticketInformation.do?eventCd=2633493&rlsCd=001 カンフェティ (WEB / 電話予約 050-3092-0051) https://www.confetti-web.com/events/17863 https://www.nohgaku.or.jp/kojanto2026', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51685', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60927, '2026-12-10', '山梨県', '野村萬斎狂言会 山梨公演', NULL, '06:00', '開場 午後6時 開演 午後6時30分 YCC県民文化ホール 小ホール ★解説 内藤連 ★狂言 昆布売 野村萬斎・高野和憲 ★狂言 合柿 野村萬斎・深田博治・飯田豪・石田淡朗・岡聡史 ●全席指定 6,500円 ※ 未就学児の入場はお断りさせていただきます 先行予約 次のいずれかの方法でお申し込みください ※重複でのお申し込みは無効 【メール】9月23日（水・祝）0:00〜9月25日（金）23:59 〔メールアドレス〕w@ybs.jp 〔入力内容〕 件名に「狂言会」、本文に�@郵便番号 �A住所 �B氏名 �C電話番号 �D枚数を明記し送信 〔抽選結果〕 9月28日（月）までに当落確認メールを送信いたします ※期間外に送信されたメールは無効となります ※メールは自動返信ではありません。当落確認メールをお待ちください。不安な方は特別電話でお申し込みください 【特別電話予約】9月25日（金）10:00〜18:00 〔電話番号〕055-231-3600 〔抽選結果〕落選の方のみ9/28（月）9:00〜18:00にお電話で連絡いたします 【共通注意事項】 ・予定枚数を超えた場合は抽選 ・座席は抽選で決定。お選びいただけません ・チケットは代金引き換えサービスで郵送します（送料660円、チケット代が50,000円を超える場合は1100円が別途かかります） ・発送時期は10月中旬以降となります。しばらくお待ちください ・先行予約はチケットの確保を目的とするものであり、良席を保証するものではありません ・お申し込み後のキャンセル・変更はできません 一般発売 10月1日（木）10:00 山日YBS本社受付 055-231-3121（平日9:00-17:00） YCC県民文化ホール 055-228-9131 ローソンチケット https://l-tike.com/ （Ｌコード：34149） e＋（イープラス） https://eplus.jp/ YCC県民文化ホールオンラインチケット 子ども無料招待 「文化庁 劇場・音楽堂等における子供舞台芸術鑑賞体験支援事業」として「子ども無料招待」とその同伴保護者の割引を、10月1日(木)午前10時から受け付けます ※公演当日、身分証での本人確認を行います。当日はアンケートにご記入いただきます ※上限に達し次第終了 ※詳細はYCC県民文化ホールのHPをご参照ください お問い合わせ、お申し込みはYCC県民文化ホールへ 電話055-228-9131 問い合わせ YCC県民文化ホール 055-228-9131 https://www.sannichi-ybs.co.jp/SP/events/mansai251211-2', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51706', 0, 0);
