INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60931, '2026-12-11', '東京都', '萬斎 イン セルリアンタワー 26', 'セルリアンタワー能楽堂', '19:00', '19時 セルリアンタワー能楽堂 解説 野村萬斎 狂言「成上り」 太郎冠者：飯田豪 主：内藤連 すっぱ：野村太一郎 後見：岡聡史 狂言「悪太郎」 悪太郎：野村萬斎 伯父：石田幸雄 僧：野村裕基 後見：高野和憲 チケット先行販売 年会費無料 オンラインチケット購入 ●S席（正面） \12,000 A席（脇正面） \10,000 B席（中正面） \8,000 学生席（座敷・自由） \4,000 数寄屋特別観覧席（食事付） ￥36,000 ※数寄屋特別観覧席（食事付）チケットはMY Bunkamuraのみにて販売いたします。 ※学生席はセルリアンタワー能楽堂のみにて取り扱います。購入の際に学生証をご提示ください。 ※未就学児の入場はご遠慮ください。 ※都合により公演の一部(出演者･曲目等)を変更する場合がございます。 ※公演中止、または主催者がやむを得ないと判断する場合以外のチケットの払い戻しはいたしません。 チケット発売日 MY Bunkamura先行発売 2026/9/10(木)10:00〜2026/9/10(木)23:59 先着制 MY Bunkamuraについて 一般発売 2026/9/11(金) 10:00 チケット取扱い チケットガイド Bunkamuraでのお申込み お電話 Bunkamuraチケットセンター（10:00〜15:00） 03-3477-9912 ＜9/11発売日初日特別電話＞ 03-3477-9999 ＜9/12以降、残席がある場合のみ取扱いあり＞ チケットカウンター ＜9/12以降、残席がある場合のみ取扱いあり＞ 東急シアターオーブ/Bunkamuraチケットカウンター＜渋谷ヒカリエ2F 11:00〜18:00＞ インターネット オンラインチケット購入 ※本公演のBunkamuraでの一般発売日＜9/11(金)＞は、Bunkamuraチケットセンター特別電話およびオンラインチケットMY Bunkamura（PC、スマートフォン）での受付となります。東急シアターオーブ／Bunkamuraチケットカウンター （店頭）での販売はございません。 ※電話または店頭でお申込みの場合は、ご利用前に必ず「Bunkamura チケット販売サービス利用規約」 &#9654; https://www.bunkamura.co.jp/ticketguide/t_kiyaku.html をご一読ください。 ※営業時間の最新情報は&#9654; https://www.bunkamura.co.jp/topics/3491.html をご確認ください。 セルリアンタワー能楽堂でのお申込み お電話 03-3477-6412 ＜平日10:00〜18:00／土日祝14:30〜17:30＞ ※能楽堂でのチケット販売は学生席のみとなります。 お問合せ セルリアンタワー能楽堂 03-3477-6412 ＜平日10:00〜18:00／土日祝14:30〜17:30＞ ※営業時間は変更になる可能性がございます。何卒ご了承ください。 https://www.ceruleantower-noh.com/lineup/2026/20261211.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51465', 0, 0);
