INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60936, '2026-12-12', '新潟県', 'プラス能「酒 ＋ 能」', 'りゅーとぴあ新潟市民芸術文化会館 能楽堂', '12:30', '時間：12:30開場 13:00開演 15:15終演予定 場所：りゅーとぴあ 新潟市民芸術文化会館 能楽堂 ★おはなし「伝統と革新の酒造り」石本龍則（石本酒造株式会社 代表取締役） ★能の解説とワークショップ ★連吟「俊寛」大松洋一・小林恆生・古澤幸正 ★仕舞「菊慈童」藤波重孝 ★仕舞「松虫 クセ」寺井栄 ★仕舞「大江山」観世三郎太 ★能「乱 置壺 双之舞」 シテ（猩々）：山階彌右衛門・関根祥丸 ワキ（高風）：大日方寛 笛：松田弘之 小鼓：田邊恭資 大鼓：原岡一之 太鼓：林雄一郎 ●料金 S席：5,500円 A席：4,500円 B席：3,500円 U25（B席）：2,000円 ※公演時25歳以下の方対象（未就学児を除く）、ご入場時に年齢がわかるものをご提示ください。 ■チケット発売日 会員：9月16日（水） 一般：9月18日（金） ※会員および一般発売日初日はインターネットと電話予約に限定させていただきます。 残席があった場合、翌営業日10:00より窓口にて取扱います。 ■チケット取扱い ・りゅーとぴあオンライン・チケット https://piagettii.s2.e-get.jp/ryutopia/pt/ ・電話 025-224-5521（10:00〜17:00／休館日除く） ・窓口（りゅーとぴあ2階） ■お問い合わせ りゅーとぴあチケット専用ダイヤル 025-224-5521（10:00〜17:00／休館日除く） https://www.ryutopia.or.jp/performance/event/42992/ https://sekineyoshimaru.jp/schedule/%e3%83%97%e3%83%a9%e3%82%b9%e8%83%bd%e3%80%8c%e9%85%92-%ef%bc%8b-%e8%83%bd%e3%80%8d/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51430', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60937, '2026-12-12', '東京都', '国立能楽堂 普及公演', '国立能楽堂', '01:00', '午後１時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 解説・能楽あんない 狂言 呼声（よびこえ） 大藏 基誠（大蔵流） 能 巻絹（まきぎぬ） 粟谷 明生（喜多流） ＊字幕あり（日本語・英語） (2026/01/07) 前売開始日 電話・インターネット予約＝11月10日（火）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou.htm', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#50045', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60938, '2026-12-12', '東京都', '朋之会', '観世能楽堂', '13:00', '13時開演 観世能楽堂 ★能 敦盛 武田祥照、田口亮二、松木崇俊、武田章志、福王和幸、金田弘明、杉信太朗、飯田清一、柿原孝則 ★狂言 三宅近成、前田晃一、三宅右矩 ★能 葛城 武田友志、舘田善博、高澤祐介、斉藤敦、曽和正博、柿原弘和、姥浦理紗 ●一般7000円 学生2000円 別途2000円で座席指定可能（ご鑑賞の5日前まで） 年間通し券（5枚セット）一般25000円 学生7000円 ■事務局（佐川方）０７０−７４７７−８１９９ hounokai2013☆gmail.com ☆を＠に変えて送信 観世ネットでも販売 https://kanze.net/publics/index/36/ http://takedamunenori.com/ http://ttmnf.or.jp/ https://takedayoshiteru.jp/ http://kobayakawa3.web.fc2.com/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#49960', 0, 0);
