INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60951, '2026-12-13', '神奈川県', '「横浜狂言堂」', '横浜能楽堂本舞台', NULL, '開場 13：00 ／ 開演 14：00 横浜能楽堂 本舞台 お話 善竹 隆司 狂言「二人大名」（大蔵流） 大藏彌太郎 狂言「濯ぎ川」（大蔵流） 善竹 隆平 ●2,500円（全席指定） お問い合わせ 横浜能楽堂 TEL：045-263-3055 https://yokohama-nohgakudou.org/schedule/3175162.html?page=2', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#50290', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60952, '2026-12-15', '愛知県', '能講座「トヨトミ イズ ダンシング〜謡・仕舞編」', NULL, NULL, '秀吉公が生まれた場所 「太閤山常泉寺」で、 前回開催した能講座 「トヨトミ イズ ダンシング」 今回は、さらに、 能を身近に感じてもらおうと、 実際の舞台稽古場を会場にして開催します。 「例 （演目）羽衣」 不時着してしまった天女と 漁師が出会い、 惹かれ合う物語。 人間と天女という 越えられない世界の違い、 一緒にいたいのに、 一緒には生きられない。 だからこそ、 相手を信じ、 自由にする。 そして最後は、 自分の幸せよりも相手の幸せを選びます。 最後に残ったのは 「あなたに出会えてよかった。」 という想い。 『羽衣』という能が、 ６００年以上もの間、 人の心を動かし続けているその理由を、 喜びや悲しみを謡い、 そして舞う・・ 実際の舞台の上で 天女の気持ちを体感してください。 全３回、下記の演目よりお届けします。 「鶴亀」 愛でたいを全力で祝う、 究極の祝祭エンタメ。 「羽衣」 天女と漁師の出会い、 羽衣をめぐる奇跡の一日。 「高砂」 ずっと一緒に、 夫婦の絆を描く、 永遠のラブストーリー。 ※「仕舞」を体験される方は 「白足袋」をご持参ください。 場所は新栄駅徒歩３分の場所になります。 初心者大歓迎、講座はどの月からでも参加できますので、 是非、お気軽にお越しください。 ＝＝＝＝＝＝＝＝＝＝＝＝ ＜愛知で能楽を普及する会＞では、 名古屋市内で能を楽しく知ってもらう「能イベント」 神社や稽古場等で気軽に学べる「能楽講座」を開催しています。 天下の三英傑の嗜み、そしてかの太閤豊臣秀吉も晩年は心酔した能の世界。 難しいと敬遠されがちな能をマンガを通じて読み解したり、 能楽師さんとのコミュニケーションを通じて、その奥深さを感じてください。 イベントでは喫茶など名古屋文化に舌鼓を打ちながら歴史を学んだり、 謡を聴いたりして「静」の時を、 講座ではじっくりと仕舞や謡を体験しながら「動」の時を、 是非、能を通じて五感を整えましょう。 詳細は下記、 愛知で能楽を普及する会 https://www.nagoya-nishio-noh.com/ 〜名古屋 西尾 能楽講座〜 公式ホームページは「名古屋西尾能」で検索。', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51452', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60953, '2026-12-15', '東京都', '能楽ちょっといい話。「高砂」', NULL, '14:00', '14:00開始／開場13:40 場所：清澄庭園【大正記念館】 講師：味方 玄（観世流シテ方） ●参加費：4,000円／青少年1,000円 ※青少年割引の対象:満 12才 ~ 26才未満・学生証提示 ※学生の方は現地決済にていったんお申込みください。 当日割引額にて受付いたします。 【参加申込�@】 e＋（イープラス）からもお申込み可能。 https://eplus.jp/nohgaku-story/ ※公演当日は発券済みのチケットをご持参ください ※チケットは全国のセブンイレブンまたはファミリーマートにてお受け取りいただけます。 【参加申込�A】 下のアイコンボタンをクリックすると予約ページに入ります。 その他のお問合せはこちらから https://www.tpac.info/contact/ https://www.tpac.info/events/detail/id=1035&state=off', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51527', 0, 0);
