INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60961, '2026-12-18', '東京都', '国立能楽堂 定例公演', '国立能楽堂', '06:00', '午後６時30分開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 ◎能作者のまなざし−観世十郎元雅− 狂言 塗師（ぬし） 茂山千五郎（大蔵流） 能 隅田川 （すみだがわ） 朝倉 俊樹（宝生流） ＊字幕あり（日本語・英語） 前売開始日 電話・インターネット予約＝11月10日（火）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou.htm', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#50046', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60962, '2026-12-18', '東京都', '第116回 野村狂言座', '観世能楽堂', '18:30', '18時半 観世能楽堂 ★解説 ★狂言 雁大名 野村裕基 野村太一郎 石田幸雄 ★狂言 因幡堂 深田博治 飯田豪 ★小舞 岡聡史 石田淡朗 竹山悠樹 ★狂言 唐人小宝 野村萬斎 野村万作 高野和憲 月崎晴夫 内藤連 中村修一 中村慶一 内藤響 ●Ｓ席7,000円 Ａ席6,000円 Ｂ席5,000円 C席4,000円 学生席3,000円 お求め先 チケットぴあ セブンイレブンでも取扱い有 カンフェティ TEL：050-3092-0051（電話受付時間 平日10：00〜17：00） ※ 学生券のご予約は一般発売日11：00より万作の会 （TEL：03-5981-9778）にて承ります。 ※ 一般発売で売切の場合、キャンセル待ちを万作の会 （TEL：03-5981-9778）にて承ります。 ■お問い合わせ先 万作の会（TEL：03-5981-9778） https://mansaku.co.jp/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#49549', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60963, '2026-12-19', '京都府', '2026年度 シリーズ能楽講座 能楽師有松遼一の「はじめての能！ 」〜能のことば、和歌のことば〜【旧三井家下鴨別邸】', NULL, NULL, '【場 所】 旧三井家下鴨別邸 2階座敷 【シリーズテーマ】 能のことば、和歌のことば 【日時と演目】 第4回：12月19日（土） 能《雪》と「朝ぼらけ」 【時 間】 10：30〜12：00 【内 容】 ・資料や映像で能の“味わい方”をやさしく解説 ・謡の体験と実演鑑賞 ・1階座敷にて抹茶とお菓子付き 【定 員】 20名程度 【料 金】 4,000円税込 （抹茶券付、入館料600円別途） ※当日受付にてお支払い 【講師】 有松 遼一 ありまつ りょういち お問い合わせ 事前申込み制。 メールにてお申し込み。 メールでのお申込み arimatsu.noh.office☆gmail.com ☆を＠に変えて送信 以下の内容を記載の上、送信してください。 �@イベント名「はじめての能！」 〇月の部とご記載ください。 �A代表者氏名 �B参加人数 �C電話番号 �D住所 �Eメールアドレス お申込み受付回答 返信メールでの回答をもって予約の成立といたします。 迷惑メール対策をされている場合、ドメインgmail.comのメールを受信できるよう設定願います。 申込締切 定員に達し次第、受付終了。 ■お問い合わせ 旧三井家下鴨別邸TEL：075-366-4321（9：00〜17：00※水曜休館） TEL 075-366-4321 お問い合わせURL https://ja.kyoto.travel/tourism/article/mitsuike/ https://ja.kyoto.travel/event/single.php?event_id=14053', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#50971', 0, 0);
