INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60977, '2026-12-20', '東京都', '梅若会定式能 12月公演', '梅若能楽学院会館', '12:00', '時間：12時30分開演 場所：梅若能楽学院会館 ★解説 ★能「野宮」 シテ：川口晃平 ワキ：則久英志 アイ：山本則重 笛：竹市学 小鼓：飯田清一 大鼓：亀井広忠 地頭：梅若紀彰 ★狂言「棒縛」 シテ：山本泰太郎 アド：山本凛太郎・山本則秀 ★舞囃子「砧 前」 シテ：鈴木矜子 笛：藤田貴寛 小鼓：幸正昭 大鼓：白坂保行 地頭：角当行雄 ★能「猩々乱 双之舞」 シテ：山本正道・山本友正 ワキ：宝生常三 笛：藤田貴寛 小鼓：幸正昭 大鼓：白坂保行 太鼓：観世結子 地頭：梅若長左衛門 ●料金 自由席：7,000円 ※正面指定料：別途1,000円（指定のご希望は公演１週間前までお申し込み下さい） ■チケット申込み 公益財団法人 梅若会 メール umewakakai.piif@gmail.com TEL 03-3363-7748（不定休） FAX 03-3363-7749 ※郵便番号、ご住所、お名前、ご連絡先電話番号、ご希望座種をお書きの上お申し込み下さい。 https://umewaka.org/schedule/1259', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51888', 0, 0);
