INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60991, '2026-12-25', '京都府', '第61回狂言五笑会', '京都府立文化芸術会館', '19:00', '19:00〜20:45（18:30開場）※予定 京都府立文化芸術会館3階和室B 【小舞】 「吉の葉」 増田浩紀 「京童」 井口竜也 「蛸」 山下守之 お 話 増田浩紀 【狂言】 「吹取」 男／島田洋海 笛の上手な男／鈴木実 ご夢想の妻／山下守之 笛／左鴻泰弘 「栗焼」 太郎冠者／増田浩紀 主 人／鈴木実 「膏薬煉」 都の膏薬煉／井口竜也 鎌倉の膏薬煉／山下守之 ●一般前売1,500円 友の会1,200円 一般当日1,800円 学生1,000円均一 チケット発売情報 一般発売：10月27日(火)午前10:00 ※未就学児童の入場はご遠慮ください。 ■お問合せ先 京都府立文化芸術会館 075-222-1046 http://www.bungei.jp/showing/13062/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51900', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60992, '2026-12-25', '東京都', '国立能楽堂 企画公演', '国立能楽堂', '06:00', '午後６時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 ◎蝋燭の灯りによる 謡講 井上 嘉介 狂言 木六駄（きろくだ） 大藏彌太郎（大蔵流） 能 籠太鼓（ろうだいこ） 辻井 八郎（金春流） ＊字幕あり（日本語・英語） 前売開始日 電話・インターネット予約＝11月10日（火）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝7,300円 脇正面＝5,700円（学生4,000円） 中正面＝4,600円（学生3,200円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou.htm', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#50047', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (60993, '2026-12-25', '福岡県', '大濠公園能楽堂 子ども能楽教室 ２０２６', '大濠公園能楽堂', '10:00', '大濠公園能楽堂 ２０２６年１２月２５日〜２７日の３日間の体験教室 10時から15時（最終日は16時） 講師 山岡晴美 久貫弘能 山本万佑子 定員15名 応募資格 小学1年生から中学3年生 3日間参加できること ＜お申し込み方法＞ 応募締切12月1日必着 申し込み保護者氏名・参加者名（ふりがな）・性別・学校名・学年・住所・電話番号・応募動機（お子様）・過去の参加の有無 を記入の上 ハガキ郵送か 申し込みフォーム（１１月１日１０：００より受付開始）で申し込み 必要なもの：白足袋（木綿）、昼食、飲み物、筆記用具 服装：動きやすいもの デニムは正座に不向きですので、おすすめいたしません また、能舞台に直接肌が触れないよう、長ズボン、スパッツなどをご着用ください ●参加費：１０，０００円（教材費・装束・仕舞扇レンタル料込） ■お問い合わせ 大濠公園能楽堂 092-715-2155 https://www.ohori-nougaku.jp/lineup/%e5%a4%a7%e6%bf%a0%e5%85%ac%e5%9c%92%e8%83%bd%e6%a5%bd%e5%a0%82%e3%80%80%e5%ad%90%e3%81%a9%e3%82%82%e8%83%bd%e6%a5%bd%e6%95%99%e5%ae%a4%e3%80%80%ef%bc%92%ef%bc%90%ef%bc%92%ef%bc%96', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2026&mon=12#51939', 0, 0);
