INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61008, '2027-01-06', '東京都', '国立能楽堂 定例公演', '国立能楽堂', '01:00', '午後１時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 素謡 神歌（かみうた） 観世 恭秀（観世流） 狂言 文蔵（ぶんぞう） 三宅 右近（和泉流） 能 邯鄲（かんたん） 佐野 登（宝生流） ＊字幕あり（日本語・英語） (2026/01/07) 前売開始日 電話・インターネット予約＝12月10日（木）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou.htm', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#50048', 0, 0);
