INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61015, '2027-01-09', '東京都', '狂言の会−茂山狂言会−いつの世も夫婦円満!?', 'セルリアンタワー能楽堂', '13:00', '13:00（12:30開場） セルリアンタワー能楽堂 終演時間 15:10頃 解説：茂山千五郎 狂言「延命袋」 夫：茂山あきら 太郎冠者：茂山千之丞 女房：茂山逸平 狂言「鎌腹」 太郎：茂山宗彦 女房：茂山竜正 仲裁人：鈴木 実 狂言「鈍太郎」 鈍太郎：茂山千五郎 下京の女：茂山 茂 上京の女：茂山虎真 ●数寄屋特別観覧席 22,000円 <数寄屋特製幕の内弁当付き> S席（正面） 8,000円 A席（脇正面） 7,000円 B席（中正面） 6,000円 学生席（座敷・自由） 3,500円 ※学生席はセルリアンタワー能楽堂のみにて取り扱い。 購入の際に学生証をご提示ください。 ※未就学児の入場はご遠慮ください。 ※都合により公演の一部(出演者･曲目等)を変更する場合がございます。 ※公演中止、または主催者がやむを得ないと判断する場合以外のチケットの払い戻しはいたしません。 ※数寄屋特別観覧席（食事付）チケットはオンラインチケットMY Bunkamuraのみにて数量限定で販売いたします。 チケット発売日 MY Bunkamura先行発売 2026/10/8(木)10:00&#12316;2026/10/8(木)23:59 先着制 MY Bunkamuraについて 一般発売 2026/10/9(金) 10:00 チケット取扱い チケットガイド Bunkamuraでのお申込み お電話 Bunkamuraチケットセンター（10:00〜15:00） 03-3477-9999 チケットカウンター 東急シアターオーブ/Bunkamuraチケットカウンター＜渋谷ヒカリエ2F 11:00〜18:00＞ インターネット オンラインチケット購入 ※Bunkamuraでの一般発売日＜10/9(金)＞は、Bunkamuraチケットセンター電話およびオンラインチケットMY Bunkamura（PC、スマートフォン）での受付となります。東急シアターオーブ／Bunkamuraチケットカウンター （店頭）での販売はございません。 ※電話または店頭でお申込みの場合は、ご利用前に必ず「Bunkamura チケット販売サービス利用規約」 &#9654; https://www.bunkamura.co.jp/ticketguide/t_kiyaku.html をご一読ください。 ※営業時間の最新情報は&#9654; https://www.bunkamura.co.jp/topics/3491.html をご確認ください。 セルリアンタワー能楽堂でのお申込み お電話 03-3477-6412 ＜平日10:00〜18:00／土日祝14:30〜17:30＞ お問合せ セルリアンタワー能楽堂 03-3477-6412 ＜平日10:00〜18:00／土日祝14:30〜17:30＞ ※営業時間は変更になる可能性がございます。何卒ご了承ください。 https://www.ceruleantower-noh.com/lineup/2027/20270109.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51673', 0, 0);
