INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61029, '2027-01-13', '東京都', '「能役者が語るヤマトの能」第1回『当麻（たえま）』', NULL, '14:00', '14:00（開場13:30）〜15:30 歌舞伎座3階花篭ホール 14:00開始（開場13:30／終了15:30頃） 場所：歌舞伎座3階 花籠ホール 講師 味方玄 （観世流シテ方） 参加費：4,000円／青少年1,000円（満12才〜26才未満の学生の方／学生証提示） ※青少年割引の対象:満 12才 ~ 26才未満・学生証提示 ※学生の方は現地決済にていったんお申込みください。 当日割引額にて受付。 【アクセス】 ※当日、歌舞伎座正面玄関からの入場はできません。 【地下鉄から】 東銀座駅から直結、歌舞伎座B2「木挽町広場」内をセブンイレブンに向かって進み、 突きあたり左手奥のエレベーターで3階へ。 【地上から】 昭和通り沿いの、歌舞伎座タワー「昭和通り口」（松石ビルの隣）を入りエレベーターで 3階へ。 【参加申込�@】イープラス e＋（イープラス）からお申込み可能です。以下リンクよりお入りください。 ※9/1（火）より申込可能となります。 https://eplus.jp/yamatononoh/ 【参加申込�A】STORES 下のアイコンボタンをクリックすると予約ページに入ります。 【お問合せはこちらから】 https://www.tpac.info/contact/ https://www.tpac.info/events/detail/id=1042&state=off', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51528', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61030, '2027-01-15', '東京都', '国立能楽堂 ショーケース', '国立能楽堂', '07:00', '午後7時開演 国立能楽堂 狂言 しびり 茂山 茂（大蔵流） 能 胡蝶（こちょう） 物着（ものぎ） 梅若 猶義（観世流） ※初心者の方にも親しみやすい作品を上演する公演です。 ＊字幕あり（日本語・英語・日本語現代語訳） (2026/01/07) 前売開始日 電話・インターネット予約＝12月10日（木）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝4,000円 脇正面＝3,400円（学生2,400円） 中正面＝2,800円（学生2,000円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#50050', 0, 0);
