INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61034, '2027-01-16', '福岡県', 'めくるめく能楽 vol.1 『喜多流』', NULL, '14:00', '14:00開演（13:30開場） 久留米シティプラザ 久留米座 ★解説 大島 衣恵 ★仕舞「高砂」粟谷 充雄 ★仕舞「八島」大島 輝久 ★狂言「末広かり」 シテ（果報者）野村 万禄 アド（太郎冠者）吉住 講 小アド（すっぱ）吉良 博靖 ★能「鶴」 シテ（鶴の精）狩野 了一 ツレ（男）狩野 祐一 笛 相原 一彦 小鼓 古田 知英 大鼓 白坂 信行 太鼓 田中 達 地謡 金子 敬一郎 内田 成信 粟谷 充雄 佐々木 多門 大島 輝久／谷 友矩 ★出演者によるアフタートーク ●〈指定席〉一般 4,000円 U30（30歳以下） 2,000円 〈自由席〉一般 3,000円 ※未就学児の入場はご遠慮ください。 ※中学生以上でU30席を購入された方は、入場時証明書をご提示ください。 ※託児サービス有（定員有／要事前予約） ※車椅子でご来場の方は事前に久留米シティプラザまでお問い合わせください。 車椅子をご利用のお客様へ 【お申込み】 座席位置・提供数に限りがございますので、チケットをご購入いただく前に、下記までお問合せください。なお、同伴の介助者がいらっしゃる場合も事前にご相談ください。 未就学児のお子様がいらっしゃるお客様へ 託児サービス（定員あり／無料） ※開場15分前から終演30分後まで、生後3ケ月から未就学児までのお子様をお預かりします。 【お申込み】 ※10月10日(土)10:00〜受付開始、12月21日(月)締切 ≪鑑賞サポートのお問い合わせ≫ メール：kcp-j@city.kurume.lg.jp TEL0942-36-3084 プレイガイド 久留米シティプラザ WEB ※会員登録（無料）が必要です ※販売状況を確認後、ログイン・会員登録（無料）することも可能です ※お席はお選びいただけます ※チケットの引取はセブンイレブン（手数料別途）又は窓口（手数料無料）を選択いただけます ※公演当日の窓口引取は大変混み合いますので、お早めにご来場ください 窓口 ※窓口営業時間 10：00〜19：00 全館保守点検による休館あり お問合せ 久留米シティプラザ（久留米市） TEL 0942-36-3000（代） FAX 0942-36-3087 https://kurumecityplaza.jp/events/8455/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51877', 0, 0);
