INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61036, '2027-01-17', '千葉県', '第10回 身近な能楽講座「猩々」', NULL, '13:00', '開場 13:00 ／ 開演 13:30 青葉の森公園芸術文化ホール（能舞台） みんなの能楽教室発表会 お話 葛西聖司（古典芸能解説者） 仕舞 屋島 松木崇俊（観世流能楽師） 仕舞 羽衣 キリ 佐川勝貴（観世流能楽師） 舞囃子 難波 猩々のお話と装束附け お話 葛西聖司 猩々 松木千俊 梅村昌功 ●無料 https://www.cbs.or.jp/aoba/events/20270117 https://www.matsunokai.com/notification/20260810-2/ ワンコイン講座 2階会議室で10時半から1時間講座があります。 こちらは500円（資料代）が必要 能楽関連展示 会場2階展示室にて、能楽に関連した展示も行います。 開催期間：2027年1月9日（土）〜1月24日（日） 期間中常設展示：10:30〜 当日特別展示（1階）：11:30〜', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51752', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61037, '2027-01-17', '大阪府', '新春天空狂言2027', '大槻能楽堂', '14:00', '14:00開演（13:30開場）大槻能楽堂 ★新春トーク 茂山逸平 × 茂山千之丞 ★狂言「二人大名」 大名甲 茂山千五郎 大名乙 茂山茂 道通り人 茂山宗彦 ★狂言「柑子」 太郎冠者 茂山あきら 主人 茂山七五三 ★作：小佐田定雄 演出：茂山あきら 新作狂言「さくらんぼ」 男 茂山千之丞 女房 茂山 逸平 友達 島田 洋海 茂山 竜正 茂山 虎真 鈴木 実 茂山千五郎 ●全席指定 6,500円 ネットワーカークラブ会員割引 6,200円 ※前売・税込み（送料別） ※当日券は500円増 ※未就学児のご入場はご遠慮ください ※車いすでご来場のお客様はセクターエイティエイトまでお問合せください チケット販売 セクターエイティエイト 06-6353-8988 （平日 10:30〜17:00、一般発売日は10:00〜） KENSYOインターネットチケットサービス プレイガイド・その他のお取扱い チケットぴあ【Pコード 545-300】 ローソンチケット【Lコード 52829】 イープラス 大槻能楽堂 06-6761-8055 一般発売：10月16日（金）10:00 https://www.nohkyogen.jp/27/tenkukyogen/index.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51789', 0, 0);
