INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61039, '2027-01-17', '石川県', '石川県立音楽堂開館25周年記念 萬斎の新春玉手箱 能楽の祝祭、琉球舞踊の華やぎ', '石川県立音楽堂', '13:15', '開場 13:15 開演 14:00 石川県立音楽堂邦楽ホール ★「翁」 翁 ：観世 清和（二十六世観世流宗家） 三番叟：野村 萬斎 千歳 ：観世 三郎太 面箱 野村裕基 笛 松田弘之 小鼓 飯田清一 住駒充彦 曽和伊喜夫 大鼓 亀井広忠 ★狂言「末廣かり」 果報者 ：野村 裕基 太郎冠者：野村 太一郎 すっぱ ：野村 萬斎 ★半能「高砂 八段之舞」 住吉明神：観世 三郎太 渡貫多聞 北島公之 笛 松田弘之 小鼓 飯田清一 大鼓 亀井広忠 太鼓 小寺真佐人 地頭 山階彌右衛門 ★「琉球舞踊集」 立方：嘉数 道彦、佐辺 良和 鹿股小夏 嘉数千季 田島吟 地謡 歌三線 仲村逸夫 喜納吏一 新垣勝裕 筝 池間北斗 笛 入嵩西諭 太鼓 宮平東亜 ●全席指定 S席 : 8,000円 A席 : 7,000円 B席 : 4,000円 チケット発売：2026年10月17日（土）10:00〜 ※未就学児の入場はご遠慮ください。 プレイガイド 音楽堂チケットボックス チケットぴあ （Pコード: 545-942） ローソンチケット （Lコード: 55685） セブンチケット （7コード: 118-031） Teket お問い合わせ 石川県立音楽堂チケットボックス Tel：076-232-8632 https://ongakudo.jp/event/detail/detail-5132/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51821', 0, 0);
