INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61046, '2027-01-23', '新潟県', '能楽堂で楽しむ四季スペシャル 雪見能', 'りゅーとぴあ新潟市民芸術文化会館 能楽堂', '13:30', '開演13:30 りゅーとぴあ新潟市民芸術文化会館・能楽堂 ★おはなし 梅内美華子 ★仕舞 箙 塩津圭介 ★仕舞 采女 大島輝久 ★仕舞 山姥 佐々木多門 ★半能 龍虎 友枝真也（喜多流）佐藤寛泰 村瀬慧 笛 藤田貴寛 小鼓 田邊恭資 大鼓 柿原孝則 太鼓 澤田晃良 地頭 金子敬一郎 ●S : 3,500円 A : 2,500円 U25 : 1,500円 【友の会フレンズ限定価格】S : 3,000円 ※U25：公演時25歳以下の方対象（未就学児除く） ご入場時に年齢のわかるものをご提示ください。 ■お問い合わせ りゅーとぴあチケット専用ダイヤル 025-224-5521 （10:00〜17:00／休館日除く） https://www.ryutopia.or.jp/performance/ticket/ ◇オンライン＆電話／発売初日10：00〜 ◇窓口／発売初日（会員先行・一般販売ともに）取扱いなし。残席がある場合には翌営業日10：00より取扱い開始 https://www.ryutopia.or.jp/performance/event/44269/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51832', 0, 0);
