INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61048, '2027-01-23', '東京都', '国立能楽堂 特別公演', '国立能楽堂', '01:00', '午後１時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 能 禅師曽我（ぜんじそが） 小倉健太郎（宝生流） 狂言 魚説法 （うおぜっぽう） 野村 萬（和泉流） 能 三輪（みわ） 神道（しんとう） 金剛 永謹（金剛流） ＊字幕あり（日本語・英語） (2026/01/07) 前売開始日 電話・インターネット予約＝12月10日（木）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝9,500円 脇正面＝7,500円（学生5,300円） 中正面＝6,500円（学生4,600円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#50051', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61049, '2027-01-23', '東京都', '第39回檀の会', '観世能楽堂', '13:00', '13時20分開場 14時開演 観世能楽堂 ★お話 葛西 聖司（古典芸能解説者） ★能 朝長 松木千俊 松木崇俊 佐川勝貴 宝生欣哉 ��澤祐介 笛 松田弘之 小鼓 成田達志 大鼓 原岡一之 太鼓 小寺真佐人 地頭 武田文志 ★狂言 梟山伏 ��澤祐介 前田晃一 金田弘明 ★お話 葛西 聖司（古典芸能解説者） ★能 岩船 松木崇俊 宝生朝哉 笛 一噌隆晴 小鼓 森澤勇司 大鼓 柿原光博 太鼓 姥浦理紗 地頭 武田志房 ●特別席15,000円 SS席13,000円 S席11,000円 A席9,000円 B席(字幕解説タブレット付）8,500円 C席6,500円 学生席3,000円 座席を指定する場合は別途2000円 B席以外の席の字幕解説用スマートフォンをご使用の場合は 別途1,500円。（各一列目の座席での使用は不可）要予約 予約はこちらから https://www.matsunokai.com/event/39th_mayuminokai/ https://www.matsunokai.com/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51753', 0, 0);
