INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61055, '2027-01-24', '静岡県', 'グランシップ伝統芸能シリーズ グランシップ静岡能（観世流）', '観世能楽堂', '14:00', '14:00開演（13:30開場） グランシップ中ホール・大地 渋沢栄一翁を主人公とした顕彰能「青淵」 〈公演時間約60分〉 【出演】 関根祥丸／渋沢篤太郎（栄一） 山階 彌右衛門 （徳川慶喜／悪鬼） 観世流能楽師 《渋沢栄一顕彰能「青淵」》 監修：観世清和 狂言監修：野村萬斎 作：中村雅之 節付：梅若紀彰 作調：亀井広忠 協力：小田幸子 ●全席指定／一般5,800円、こども・学生1,000円 ※未就学児入場不可 プレイガイド グランシップ窓口 グランシップチケットセンター TEL. 054-289-9000 オンラインチケット販売 問合せ グランシップチケットセンター TEL.054-289-9000 車椅子をご利用の方へ 車椅子でご来場の方は、公演前日までにご連絡ください 託児サービスをご希望の方へ 託児サービスをご希望の方は、公演のチケットをご購入のうえ、 週間前までにお電話でお申込みください。（TEL:054-203-5714） ２歳以上、未就学児に限ります。 公演当日、お着物で来場の方へ、観世能楽堂オリジナルグッズをプレゼント https://www.granship.or.jp/visitors/event/detail.php?id=3612', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51825', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61056, '2027-01-26', '東京都', '国立能楽堂ガイドツアー', '国立能楽堂', '02:00', '令和9年 1月26日（火）午後2時／午後7時 3月4日（木）午後2時／午後7時 ※ツアー所要時間 約2時間 ※開場時間は、各回開始1時間前 見学場所 国立能楽堂 能舞台・楽屋・客席・ロビー・展示室（1/26、3/4） ※ミニ鑑賞および能楽体験付き ※英語通訳あり ※靴を脱ぎ、靴下に履き替えていただく場所がございます（靴下は貸出します）。 ※写真撮影OK（一部撮影不可エリアあり） ご案内 令和9年 1月26日（火）午後2時／午後7時 未定 3月4日（木）午後2時／午後7時 未定 ●参加料金 4,000円 ※各回40名様限定 ※施設見学のみ（客席・ロビー・展示室（1/26、3/4））は、予約不要・無料です。ミニ鑑賞・体験はできません。 ［見学時間：午後2時30分〜午後4時（11/27除く）、午後7時30分〜午後9時］ 予約開始 令和9年 1月26日（火）の回：令和8年12月10日（木）午前10時 3月4日（木）の回：令和9年2月10日（水）午前10時 ※売り切れの場合がございますので、予めご了承ください。 【電話】国立劇場チケットセンター 0570（07）9900 https://www.ntj.jac.go.jp/topics/nou/2026/guidedtour2026/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51735', 0, 0);
