INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61067, '2027-01-31', '大阪府', '春の謡会2027', '大槻能楽堂', '15:20', '15:20開場／16:00開演／19:00終演予定 大槻能楽堂 〒540-0005 大阪市中央区上町A-7 【能楽】 能「紅葉狩」大槻裕一 ほか 【現代音楽】 吉澤嘉代子、内澤崇仁（androp） 【ナビゲーター】 深町絵里（FM802） ●4,000円（税込・全席指定・前売当日共） チケット発売日 �@公式サイト先行（抽選）：10月16日(金)14:00〜10月31日(土)23:59 受付URL：e＋（イープラス） https://eplus.jp/sf/detail/4034170001?P6=001&P1=0402&P59=1 �Aプレイガイド先行（抽選）：受付詳細は後日ご案内させていただきます �B一般発売日（先着）：11月28日(土)10:00〜各プレイガイドにて発売開始 プレイガイド e+（イープラス） ローソンチケット チケットぴあ FANYチケット CNプレイガイド 【注意事項】 ※未就学児童入場不可 ※お一人様1公演につき、1席種4枚まで お問い合わせ 【公演に関するお問合せ】 FANYチケット問合せダイヤル TEL：0570-550-100（10:00〜19:00） https://osaka-ca-fes.jp/project/event/harunoutakai2027/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51838', 0, 0);
