INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61069, '2027-01-31', '東京都', '第４６回初春の会 手話狂言', '国立能楽堂', '13:30', '13時半 国立能楽堂 手話狂言 「萩大名」 「文 荷」 「牛盗人」 出演予定 黒柳徹子 三宅狂言会(声の出演) 小泉文子、五十嵐由美子、鈴まみ、砂田アトム、數見陽子 江副悟史、長谷川翔平、五日市十夢、野�ｱ誠、守屋水結 ●SS席 7,000円 S席 6,000円 A席 4,500円 B席 3,000円 ※団体割引（S席A席 B席）4人以上で各席500円引き １０月２８日（水）午前１０時チケット発売開始 https://mailform.mface.jp/frms/jtd/uc1x9oxjpvzg https://ameblo.jp/jtd2009/entry-12980885174.html ぴあも取り扱いあり https://t.pia.jp/pia/ticketInformation.do?eventCd=2638680&rlsCd=001&lotRlsCd=', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51858', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61070, '2027-01-31', '神奈川県', '空花 ARTS PROJECT 箏×バレエ×能へのいざない 空花の集い', NULL, NULL, '中原市民館 （東急東横線・目黒線、JR南武線、JR横須賀線 武蔵小杉駅より徒歩3分、4分） 〒211-0004 神奈川県川崎市中原区新丸子東３丁目１１００−１２ パークシティ武蔵小杉ミッドスカイタワー １・２階 【第一部 公演】観て楽しむ 箏曲 沢井比河流作曲 「イリュージョン」 えっ！ 箏でバッハ!?「メヌエット(ト長調)」 【二重奏】滝川美鶴 外山香 バレエ バレエ小品集 三沢範子 浜里美 針生朋美 能楽 仕舞「船弁慶」角当直隆 仕舞「小袖曽我」角田勝美 角当美織 能装束着付特別披露 山中が晶 【第二部 体験】触れて楽しむ それぞれのジャンルの体験ブースを自由にご覧いただくことができます。 また、実際に体験をご希望される方は、受付にてお申込みください。（先着順 定員あり） 箏の部 箏の体験 定員18名 一人15分 実際に爪をつけて、さくらさくらの一節を弾いてみることができます。 箏の展示あり バレエの部 バレエの動きの体験 定員20名 バレエの衣装の展示あり 能楽の部 能面体験 定員30名 一人5分・交代制 実際に能面の目の穴から視野を確認していただけます。 謡の体験 定員なし 一人15分・交代制 結婚式でおなじみの「高砂」を体験していただきます。本来は、正座で謡いますが、今回は、椅子に座って謡います。 能装束の展示あり ●一般 2,800円（前売り2,500円） 親子 大人＋小学生以下 2,800円（前売り2,500円） 必ず小学生以下の方の人数をお伝えください。 中高生 1,000円 小学生以下（無料）を含むお申込みの方は、親子チケットをお買い求めください。 チケットのお申込みはこちらから https://sorahana-arts.com/sorahananotsudoi/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51883', 0, 0);
