INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61072, '2027-01-31', '群馬県', '第十八回 いせさき能', NULL, '02:00', '午後2時開演（午後1時30分開場）、伊勢崎市 会場：人材派遣ワイズコーポレーション境総合文化センター 大ホール ★仕舞「夕顔」梅若 志長 ★仕舞「玉蔓」梅若 紀佳 ★仕舞「源氏供養」梅若 紀長 ★狂言「文山賊」野村 裕基、飯田 豪 ★能：「半蔀 立花供養」加藤 眞悟、梅村 昌功、深田 博治 ■入場料： 指定席：SS席 7,000円 / S席 6,000円 / A席 5,000円 自由席：B席 3,000円 / 大学生 1,000円 / 高校生以下 無料 ※当日券は各種500円増し チケット予約（下記窓口で直接受付中） 〇 人材派遣会社ワイズコーポレーション境総合文化センター （伊勢崎市境総合文化センター） 〇 ナルセグループ伊勢崎市民プラザ 〇 赤堀芸術文化プラザ ●カンフェティ（ネット販売・準備中） https://www.confetti-web.com/events/17711 https://isesakinou.amebaownd.com/posts/59203515', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=1#51767', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61073, '2027-02-03', '東京都', '国立能楽堂 定例公演', '国立能楽堂', '01:00', '午後１時開演 国立能楽堂 ※開場時間は、開演の１時間前の予定 《月間特集 絵巻物と能》 狂言 千切木（ちぎりき） 三宅 右矩（和泉流） 能 百万（ひゃくまん） 今井 清隆（金剛流） ＊字幕あり（日本語・英語） (2026/01/07) 前売開始日 電話・インターネット予約＝1月10日（日）午前10時より ※国立能楽堂チケット売場窓口・自動発券機は国立能楽堂主催公演日（＊）のみの営業（午前10時〜午後6時）です。＊販売開始は電話・インターネット予約開始日の翌日以降 ※窓口販売用に別枠でのお取り置きはございません。 等級別料金 正面＝5,800円 脇正面＝4,000円（学生2,800円） 中正面＝3,500円（学生2,500円） ※インターネットでも学生料金・障害者割引（2割引）による申し込みが可能です（他の割引との併用不可）。 ※車椅子用スペースがございます。詳細はチケットセンターまでお問い合わせください。 お問い合わせ 国立劇場チケットセンター（午前10時〜午後6時） 0570-07-9900／03-3230-3000(一部IP電話等) インターネット購入 https://ticket.ntj.jac.go.jp/ https://www.ntj.jac.go.jp/nou/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=2#50053', 0, 0);
INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61074, '2027-02-03', '東京都', '第一回 祥丸之會', '観世能楽堂', '18:30', '18:30開演 観世能楽堂 ★解説 竹内晶子 ★仕舞 梅 観世清和 ★能 弱法師 関根祥丸 宝生常三 野村太一郎 笛 一噌隆之 小鼓 観世新九郎 大鼓 亀井広忠 地頭 観世清和 ●S席10000円 A席8000円 B席6000円 C席4000円 学生各席2000円引き 一般発売 12月15日10時 祥の会会員先行予約 11月1日〜20日 先行予約受付 観世能楽堂 ０３−６２７４−６５７９ https://kanze.net/ https://sekineyoshimaru.jp/ https://www.instagram.com/sekine_yoshimaru/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=2#51530', 0, 0);
