INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61076, '2027-02-06', '京都府', '渡邊守章記念 春秋座―能と狂言', NULL, '13:30', '13時半開場 14時開演 京都芸術劇場 春秋座（京都芸術大学内） プレトーク「演出をめぐって」 片山九郎右衛門（観世流シテ方） 天野文雄（大阪大学名誉教授） 狂言『名取川』 シテ（僧）：野村万作、アド（名取の何某）：野村裕基 地謡：飯田豪、中村修一、内藤連 能『熊野 読次之伝 村雨留』 シテ（熊野）：観世銕之丞 ツレ：（朝顔） 観世淳夫 ワキ（平宗盛） 宝生常三 ワキツレ（太刀持） 舘田善博 笛：竹市学、小鼓：大倉源次郎、大鼓：亀井広忠 地謡：片山九郎右衛門、味方玄、浦田保親、片山伸吾、分林道治、橋本忠樹、安藤貴康、浅井風矢 チケット発売日 友の会先行 11月10日（火）10:00 一般発売 11月11日（水）10:00 ※友の会先行発売は、2026年10月26日（月）までのご入会でご利用いただけます。ご入会はこちら ※チケット発売日は、チケットセンター窓口での販売はいたしません。 オンラインチケットストアをご利用いただくか、お電話にてお申込みください。 ●（全席指定） 一階席 一 般 7,500円 一階席 友の会 7,000円 二階席 一 般 6,500円 二階席 友の会 6,000円 学生＆ユース 2,500円 ※未就学児入場不可 ※ユースは25歳以下。ユースは入場時に身分証明書をご提示ください。 託児サービス（要事前予約） 対象：生後6ヵ月以上7歳未満 料金：お子様1名につき1,500円 申込期間：2026年11月10日（火）10:00〜2027年1月29日（金）17:00 ■託児予約・お問合せ 京都芸術大学舞台 芸術研究センター （平日10:00〜17:00） TEL 075-791-9207 本公演は「令和８年度 文化庁 劇場・音楽堂等における子供舞台芸術鑑賞体験支援事業」に採択されました。 18才以下の方は無料*、ご同伴者様は半額*で鑑賞いただけます（要事前申込）。 *無料対象は平成20年（2008年）4月2日以降に生まれた方です。 *半額対象となる人数には要件があります。 https://k-pac.org/events/16364/', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=2#51820', 0, 0);
