INSERT INTO "show_info" ("id", "showdate", "prefucture", "showname", "venues", "starttime", "memo", "url", "favorite", "new") VALUES (61118, '2027-03-12', '京都府', '第285回市民狂言会', '京都観世会館', '18:30', '18時半開場 19時開演 京都観世会館 ★解説 茂山千之丞 ★狂言 子盗人 茂山千五郎 茂山茂 茂山忠三郎 ★狂言 察化 茂山あきら 茂山宗彦 松本薫 ★狂言 子の日 茂山逸平 鈴木実 ●S席 1階指定席 一般 前売券4,000円 当日券4,500円 A席 1階指定席 一般 前売券3,000円 当日券3,500円 キャンパス文化パートナーズ 前売券・当日券1,500円 高校生以下 前売券・当日券 1,000円 学生証を提示 B席 2階自由席 一般 前売券・当日券 2,000円 高校生以下 前売券・当日券1,000円 学生証を提示 京都市キャンパス文化パートナーズ制度加入学生は、A席を1,500 円でご購入いただけます。取扱は京都芸術センター窓口のみ。学生証および携帯会員証をご提示ください。 前売券の取り扱い 京都芸術センター、 チケットぴあ キャンパス文化パートナーズ制度割引チケットは京都芸術センターのみの取扱い 第283回以降の各回については前回開催日に会場にて先行販売。またその翌日から上記プレイガイドにて販売開始予定 第285回：令和9年3月12日（金曜日）12月5日（土）発売 Pコード５４０−５００ http://www.kyoto-kanze.jp/ https://www.city.kyoto.lg.jp/bunshi/page/0000350648.html', 'https://nohgaku.fan.coocan.jp/schedule/sche36.cgi?cm=&mode=&year=2027&mon=3#50493', 0, 0);
